\label{thm:5}
Let $\psi$ be an eigenfunction of (\ref{eq:se}). Define $m(x,y) = \min\{1, |x|, |y| \}$. Then for all $|\alpha|+|\beta| =5$ we have $C$, depending on $Z,N$ and $E$, such that
\begin{align}
\label{eq:5}
|\partial_x^{\alpha}\partial_y^{\beta}\gamma(x,y)| \le 
\begin{cases}
Cm(x,y)^{-3}
\left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(x, 1))} \left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(y, 1))} \quad &\text{if } |\alpha|,|\beta|\ge 1 \\
Cm(x,y)^{-4}
\left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(x, 1))} \left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(y, 1))} \quad &\text{otherwise}\\
\end{cases}
\end{align}
for all $x,y \in \mathbb{R}^3$ obeying $0<|x-y| \le m(x,y)/2$.

\begin{enumerate}

\item 
The bound (\ref{eq:5}) naturally complements (\ref{eq:hearnsob}) and (\ref{eq:hearnsob2}) for $|\alpha|+|\beta| \ne 5$.
\item 
As a consequence of \cite[Proposition A.1]{hearn_sob2} and Sobolev embeddings, the inequality (\ref{eq:5}) shows that $\gamma\in C^{4, 1}
\big(( \mathbb R^3\backslash\{0\})\times( \mathbb R^3\backslash\{0\})\big)$. The definition of this space is given after Remark \ref{rem:ddpsi} below.
\item
In view of \cite[Remark 1.2(7)]{hearn_sob2}, the boundedness of the fifth derivative at the diagonal is consistent with the asymptotics of eigenvalue decay of the density matrix operator given in \cite{sob_asymptotics}. In addition, such analysis indicates the sixth derivative will in general be unbounded.
\end{enumerate}

\label{thm:ddpsi}
For every cluster set $\bold{P} = (P_1, \dots, P_M)$, multiindex $\boldsymbol{\alpha} \in \mathbb{N}_0^{3M}$ and any $R>0$ there exists $C$, depending on $\boldsymbol\alpha$ and $R$, such that for $k=0,1$,

\begin{equation}
\label{eq:ddpsi}
|D_{\bold{P}}^{\boldsymbol{\alpha}}\nabla^{k} \psi(\mathbf x)| \le C \lambda_{\boldsymbol{\alpha}}(\bold{x})^{1-k} \lambda_{P_1}(\bold{x})^{-|\alpha_1|} \dots \lambda_{P_M}(\bold{x})^{-|\alpha_M|}
f_{\infty}(\bold{x}; R)
\end{equation}
for all $\bold{x} \in \Sigma^c_{\boldsymbol{\alpha}}$.

Furthermore, for each $|\boldsymbol\alpha| \ge 1$ there exists a function $G_{\bold{P}}^{\boldsymbol{\alpha}} : \Sigma^c_{\boldsymbol\alpha} \to \mathbb{C}^{3N}$ such that
\begin{equation}
\label{eq:gp_def}
D_{\bold{P}}^{\boldsymbol{\alpha}}\nabla \psi = G_{\bold{P}}^{\boldsymbol{\alpha}} + \psi\, D_{\bold{P}}^{\boldsymbol\alpha}\nabla F_c,
\end{equation}
where $F_c$ is defined later in (\ref{f_def}), and for each $0\le b<1$ there exists $C$, depending on $\boldsymbol\alpha, R$ and $b$, such that
\begin{equation}

\label{eq:gp_bnd}
|G_{\bold{P}}^{\boldsymbol{\alpha}}(\bold{x})| \\\le C \mu_{\boldsymbol\alpha}(\bold{x})^b \lambda_{P_1}(\bold{x})^{-|\alpha_1|} \dots \lambda_{P_M}(\bold{x})^{-|\alpha_M|} f_{\infty}(\bold{x}; R )
\end{equation}
for all $\bold{x} \in \Sigma^c_{\boldsymbol{\alpha}}$.

\label{rem:ddpsi}
\begin{enumerate}
\item
In the case of a single cluster and $k=0$, the bound (\ref{eq:ddpsi}) reestablishes (\ref{eq:fs_p}) in the case of $p = \infty$, albeit with a larger radius in the $L^{\infty}$-norms on the right-hand side, which doesn't concern us.
\item
The presence of a single power of $\lambda_{\boldsymbol\alpha}(\mathbf x)$ in the bound (\ref{eq:ddpsi}), for $k=0$, will cancel a single negative power of the smallest $\lambda_{P_j}(\mathbf x)$ for $j$ such that $\alpha_j \ne 0$. Notice that the appropriate $j$ will depend on $\mathbf x$.
\item
The bound in (\ref{eq:gp_bnd}) is stronger than that of (\ref{eq:ddpsi}) with $k=1$. This is because a positive power of $\mu_{\boldsymbol\alpha}(\mathbf x)$ will partially cancel a single negative power of the largest $\lambda_{P_j}(\mathbf x)$ for $j$ such that $\alpha_j \ne 0$. The term $\psi\, D_{\bold{P}}^{\boldsymbol\alpha}\nabla F_c$ in (\ref{eq:gp_def}) only obeys a bound as in (\ref{eq:ddpsi}) for $k=1$, therefore represents the part of $D_{\bold{P}}^{\boldsymbol{\alpha}}\nabla \psi$ which inhibits an improved derivative bound.
\end{enumerate}

\label{thm:c1}
Let $x_0 \in \mathbb{R}^{n}$, $R>0$ and $\bold{c}, d, g \in L^{\infty}(B(x_0, R))$ and $u \in H^1(B(x_0, R))$ be a weak solution to (\ref{eq:pde}) then for each $\theta \in [0,1)$ we have $u \in C^{1, \theta}(B(x_0, R)) \cap H_{loc}^2(B(x_0, R))$, and for any $r \in (0,R)$ we have
\begin{equation}
\label{c1_er_eqn}
\left\lVertu\right\rVert_{C^{1,\theta}(\overline{B(x_0, r)})} \le C(\left\lVertu\right\rVert_{L^2(B(x_0, R))} + \left\lVertg\right\rVert_{L^{\infty}(B(x_0, R))})
\end{equation}
for $C=C(n,  K, r, R, \theta)$ where

\begin{equation*}
\left\lVert\bold{c}\right\rVert_{L^{\infty}(B(x_0, R))} + \left\lVertd\right\rVert_{L^{\infty}(B(x_0, R))} \le K.
\end{equation*}

\label{mu_lemma}
For any $\boldsymbol{\sigma} = (\sigma_1, \dots, \sigma_M) \in \mathbb{N}_0^{3M}$ we have for $k=0,1$,
\begin{equation}
\label{mu_1sig}
\mu_{\boldsymbol{\sigma}}(\bold{y})^{k-|\boldsymbol{\sigma}|} \le \lambda_{\boldsymbol{\sigma}}(\bold{y})^{k} \lambda_{P_1}(\bold{y})^{-|\sigma_1|} \dots \lambda_{P_M}(\bold{y})^{-|\sigma_M|}
\end{equation}
for all $\bold{y} \in \mathbb{R}^{3N}$. Furthermore, for some $n \ge 1$ let $\boldsymbol{\beta}^{(1)}, \dots, \boldsymbol{\beta}^{(n)}$ be an arbitrary collection of multiindices in $\mathbb{N}_0^{3M}$ such that $\boldsymbol{\beta}^{(1)} + \dots + \boldsymbol{\beta}^{(n)} = \boldsymbol{\sigma}$, then
\begin{equation}
\label{lam_prod}
\prod_{j=1}^n  \lambda_{\boldsymbol{\beta}^{(j)}}(\bold{y}) \le \lambda_{\boldsymbol{\sigma}}(\bold{y})
\end{equation}
for all $\bold{y} \in \mathbb{R}^{3N}$.

The results are trivial in the case of $\boldsymbol{\sigma} = 0$ therefore we assume in the following that $\boldsymbol{\sigma}$ is non-zero. First, observe for all $j=1, \dots, M$,
\begin{equation*}
\begin{split}
\mu_{\boldsymbol{\sigma}}(\bold{y})^{-|\sigma_j|} &\le \lambda_{P_j}(\bold{y})^{-|\sigma_j|}\\
\mu_{\boldsymbol{\sigma}}(\bold{y})^{1-|\sigma_j|} &\le \lambda_{P_j}(\bold{y})^{1-|\sigma_j|} \quad \text{ if } \sigma_j \ne 0
\end{split}
\end{equation*}
by the definition of $\mu_{\boldsymbol{\sigma}}$. Now perform the following trivial expansion of the product,
\begin{equation*}
\begin{split}
\mu_{\boldsymbol{\sigma}}(\bold{y})^{-|\boldsymbol{\sigma}|} &= \mu_{\boldsymbol{\sigma}}(\bold{y})^{-|\sigma_1|} \dots \mu_{\boldsymbol{\sigma}}(\bold{y})^{-|\sigma_M|}\\
&\le \lambda_{P_1}(\bold{y})^{-|\sigma_1|} \dots \lambda_{P_M}(\bold{y})^{-|\sigma_M|}
\end{split}
\end{equation*}
which proves (\ref{mu_1sig}) for $k=0$. For $k=1$, consider that for each $\bold{y}$ we can find $l = 1, \dots, M$ such that $\lambda_{\boldsymbol{\sigma}}(\bold{y}) = \lambda_{P_l}(\bold{y})$ and $\sigma_l \ne 0$. Then,
\begin{equation*}
\begin{split}
\mu_{\boldsymbol{\sigma}}(\bold{y})^{1-|\boldsymbol{\sigma}|} &= \mu_{\boldsymbol{\sigma}}(\bold{y})^{-|\sigma_1|} \dots \mu_{\boldsymbol{\sigma}}(\bold{y})^{1-|\sigma_l|} \dots \mu_{\boldsymbol{\sigma}}(\bold{y})^{-|\sigma_M|}\\
&\le  \lambda_{P_1}(\bold{y})^{-|\sigma_1|}  \dots \lambda_{P_l}(\bold{y})^{1-|\sigma_l|} \dots \lambda_{P_M}(\bold{y})^{-|\sigma_M|}\\
&=  \lambda_{\boldsymbol{\sigma}}(\bold{y}) \lambda_{P_1}(\bold{y})^{-|\sigma_1|} \dots \lambda_{P_M}(\bold{y})^{-|\sigma_M|}
\end{split}
\end{equation*}
as required.

\paragraph{}
Finally we prove (\ref{lam_prod}). As above, take arbitrary $\bold{y}$ and a corresponding $l$ such that $\lambda_{\boldsymbol{\sigma}}(\bold{y}) = \lambda_{P_l}(\bold{y})$ with $\sigma_l \ne 0$. For each $1 \le j \le n$ we denote the $\mathbb{N}_0^3$-components of $\boldsymbol{\beta}^{(j)}$ as $\boldsymbol{\beta}^{(j)} = (\beta^{(j)}_1, \dots, \beta^{(j)}_M)$. We know $\boldsymbol{\beta}^{(1)} + \dots + \boldsymbol{\beta}^{(n)} = \boldsymbol{\sigma}$ so in particular, $\beta_l^{(1)} + \dots + \beta_l^{(n)} = \sigma_l$. Since $\sigma_l \ne 0$ there exists at least one $1 \le r \le n$ such that $\beta^{(r)}_{l} \ne 0$. Hence by the definition of $\lambda_{\boldsymbol{\beta}^{(r)}}$,
\begin{equation*}
\lambda_{\boldsymbol{\beta}^{(r)}}(\bold{y}) = \min\{\lambda_{P_s}(\bold{y}) : \beta_s^{(r)} \ne 0 \text{, } s = 1, \dots, M \} \le \lambda_{P_l}(\bold{y}) = \lambda_{\boldsymbol{\sigma}}(\bold{y}).
\end{equation*}
The remaining factors $\lambda_{\boldsymbol{\beta}^{(j)}}(\bold{y})$, for $j \ne r$, can each be bounded above by one.

\label{der_F}
Let $f \in C^{\infty}(\mathbb{R}^3 \backslash \{0 \})$ and $k \in \mathbb{N}_0$ be such that for each $\sigma \in \mathbb{N}_0^3$ there exists $C$ such that
\begin{equation}
\label{dsf_ineq}
|\partial^{\sigma} f(x)| \le C|x|^{k-|\sigma|} \text{ for all } x \ne 0. 
\end{equation}
Then for any $\boldsymbol{\alpha} \ne 0$ with $|\boldsymbol{\alpha}| \ge k$ there exists some new $C$ such that for any $l,m = 1, \dots, N,$ the weak derivatives $D_{\bold{P}}^{\boldsymbol{\alpha}}(f(x_l))$ and $D_{\bold{P}}^{\boldsymbol{\alpha}}(f(x_l - x_m))$ are both smooth in $\Sigma_{\boldsymbol{\alpha}}^c$ and obey
\begin{equation*}
|D_{\bold{P}}^{\boldsymbol{\alpha}}(f(x_l))|,\, |D_{\bold{P}}^{\boldsymbol{\alpha}}(f(x_l - x_m))| \le Cq_{\boldsymbol{\alpha}}(\bold{x})^{k-|\boldsymbol{\alpha}|}
\end{equation*}
for all $\bold{x} \in \Sigma_{\boldsymbol{\alpha}}^c$.

Take any $j = 1, \dots, M$ with $\alpha_j \ne 0$, then we have $D^{\alpha_j}_{P_j}(f(x_l)) \equiv 0$ for each $l \in P_j^c$. Therefore, for $D^{\boldsymbol{\alpha}}_{\bold{P}} (f(x_l))$ to not be identically zero we require that $l \in P_j$ for each $j$ with $\alpha_j \ne 0$. For such $l$ we have $x_l \ne 0$ since $\bold{x} \in \Sigma^c_{\boldsymbol{\alpha}}$, and
\begin{equation*}
|x_l| \ge d_{P_j}(\bold{x})
\end{equation*}
for each $j$ with $\alpha_j \ne 0$ by (\ref{dp_def}). Therefore, for constant $C$ in (\ref{dsf_ineq}), we have
\begin{equation*}
|D^{\boldsymbol{\alpha}}_{\bold{P}} (f(x_l))| = |\partial^{\alpha_1 + \dots + \alpha_M}f(x_l)| \le C|x_l|^{k-|\boldsymbol{\alpha}|} \le Cq_{\boldsymbol{\alpha}}(\bold{x})^{k-|\boldsymbol{\alpha}|}
\end{equation*}
because $|\boldsymbol{\alpha}| \ge k$. Similarly, for each $j = 1, \dots, M$, with $\alpha_j \ne 0$ we have $D^{\alpha_j}_{P_j} (f(x_l - x_m)) \equiv 0$ if either $l, m \in P_j$ or $l, m \in P_j^c$. Therefore, for $D^{\boldsymbol{\alpha}}_{\bold{P}} (f(x_l - x_m))$ to not be identically zero we require that
\begin{equation*}
(l,m) \in \bigcap_{j \,:\, \alpha_j \ne 0} \big((P_j \times P_j^c) \cup (P_j^c \times P_j)\big).
\end{equation*}
For such $(l,m)$ we have $x_l \ne x_m$ since $\bold{x} \in \Sigma^c_{\boldsymbol{\alpha}}$ and
\begin{equation*}
 |x_l - x_m| \ge \sqrt{2}\, d_{P_j}(\bold{x})
\end{equation*}
for each $j$ with $\alpha_j \ne 0$ by (\ref{dp_def}). Therefore, for some constant $C'$,
\begin{equation*}
|D^{\boldsymbol{\alpha}}_{\bold{P}} (f(x_l - x_m))| = |\partial^{\alpha_1 + \dots + \alpha_M}f(x_l - x_m)| \le C|x_l - x_m|^{k - |\boldsymbol{\alpha}|} \le C' q_{\boldsymbol{\alpha}}(\bold{x})^{k-|\boldsymbol{\alpha}|}
\end{equation*}
because $|\boldsymbol{\alpha}| \ge k$.

\label{der_gradF}
For any cluster set $\bold{P}$ and any $|\boldsymbol\sigma| \ge 1$ there exists $C$, which depends on $\boldsymbol{\sigma}$, such that for $k=0,1$,



\begin{equation}
\label{dd_f_ef}
\big|D_{\bold{P}}^{\boldsymbol{\sigma}}\nabla^k F(\bold{y})\big|, \, \big|D_{\bold{P}}^{\boldsymbol{\sigma}} \nabla^k (e^{F})(\bold{y})\big| \le  C \lambda_{\boldsymbol{\sigma}}(\bold{y})^{1-k} \lambda_{P_1}(\bold{y})^{-|\sigma_1|} \dots \lambda_{P_M}(\bold{y})^{-|\sigma_M|}
\end{equation}
\begin{equation}
\label{dd_f_2}
\big|D_{\bold{P}}^{\boldsymbol{\sigma}} |\nabla F(\bold{y})|^2\big| \le C\lambda_{P_1}(\bold{y})^{-|\sigma_1|} \dots \lambda_{P_M}(\bold{y})^{-|\sigma_M|}
\end{equation}
for all $\bold{y} \in \Sigma^c_{\boldsymbol{\sigma}}$. The bound to the first quantity in (\ref{dd_f_ef}) also holds when $F$ is replaced by $F_c$.

Let $\tau$ be the function defined as $\tau(x) = |x|$ for $x \in \mathbb{R}^{3}$. Then, by definition (\ref{f_def}) we can write
\begin{equation}
\label{dpf1}
F_c(\bold{y}) = -\frac{Z}{2}\sum_{1 \le j \le N}\tau(y_j) + \frac{1}{4}\sum_{1\le l<m \le N} \tau(y_l - y_m).
\end{equation}
For each $r=1,\dots,N$, denote by $\nabla_{y_r}$ the three-dimensional gradient in the variable $y_r$. We then have
\begin{equation}
\label{ddpf1}
\nabla_{y_r} F_c(\bold{y}) = -\frac{Z}{2} \nabla \tau(y_r) +  \frac{1}{4}\sum_{\substack{m=1 \\ m \ne r}}^{N} \nabla \tau(y_r - y_m).
\end{equation}
We apply the $D^{\boldsymbol{\sigma}}_{\bold{P}}$-derivative to each of (\ref{dpf1}) and (\ref{ddpf1}), using Lemma \ref{der_F} with $f = \tau$ and $f = \nabla \tau$ respectively. This shows that for $k=0,1$ the functions $D_{\bold{P}}^{\boldsymbol{\sigma}} \nabla^{k} F_c$ exist and are smooth on the set $\Sigma^c_{\boldsymbol{\sigma}}$. Furthermore, there exists $C$, depending on $\boldsymbol{\sigma}$, such that
\begin{align}
\label{ddpf1_ineq}
|D_{\bold{P}}^{\boldsymbol{\sigma}} \nabla^{k} F_c(\bold{y})| &\le Cq_{\boldsymbol{\sigma}}(\bold{y})^{1-k-|\boldsymbol{\sigma}|} \le C\mu_{\boldsymbol{\sigma}}(\bold{y})^{1-k-|\boldsymbol{\sigma}|}
\end{align}
for all $\bold{y} \in \Sigma^c_{\boldsymbol{\sigma}}$. In the second inequality we used that $\mu_{\boldsymbol{\sigma}}(\bold{y}) \le q_{\boldsymbol{\sigma}}(\bold{y})$.


Recall that $\nabla F_s$ is smooth with all derivatives bounded, see (\ref{f2_linf}). Since $F = F_c-F_s$ and $\mu_{\boldsymbol{\sigma}} \le 1$, we have that for each $\boldsymbol{\sigma} \ne 0$ and $k=0,1$, there exists $C$, depending on $\boldsymbol{\sigma}$, such that
\begin{equation}
\label{dd_f}
|D_{\bold{P}}^{\boldsymbol{\sigma}}\nabla^k F(\bold{y})| \le C\mu_{\boldsymbol{\sigma}}(\bold{y})^{1-k-|\boldsymbol{\sigma}|}
\end{equation}
for all $\bold{y} \in \Sigma^c_{\boldsymbol{\sigma}}$. By a straightforward application of Lemma \ref{mu_lemma}, this proves the first bound in (\ref{dd_f_ef}), for $k=0,1$.



\paragraph{}
We proceed to prove the second bound in (\ref{dd_f_ef}). For every $\boldsymbol{\eta} \le \boldsymbol{\sigma}$ we have that $\Sigma_{\boldsymbol{\eta}} \subset \Sigma_{\boldsymbol{\sigma}}$ and therefore $D_{\bold{P}}^{\boldsymbol{\eta}} \nabla^k F$ exists and is smooth in $\Sigma_{\boldsymbol{\sigma}}^c$, for $k=0,1$. We use the chain rule for weak derivatives to show that $D^{\boldsymbol{\sigma}}_{\bold{P}}(e^F)$ exists in $\Sigma_{\boldsymbol{\sigma}}^c$ and is equal to a sum of terms, each of the form
\begin{equation}
\label{dp_ef}
e^F \prod_{1 \le j \le n} D^{\boldsymbol{\beta}^{(j)}}_{\bold{P}}F
\end{equation}
for some $1 \le n \le |\boldsymbol{\sigma}|$ and some collection $0 \ne \boldsymbol{\beta}^{(j)} \in \mathbb{N}_0^{3M}$ for $j=1,\dots,n$, where $\boldsymbol{\beta}^{(1)} + \dots + \boldsymbol{\beta}^{(n)} = \boldsymbol{\sigma}$. 

For each $j=1,\dots,n$, we write $\boldsymbol{\beta}^{(j)} = (\beta^{(j)}_1, \dots, \beta^{(j)}_{M})$ to denote the $\mathbb{N}_0^3$-components of $\boldsymbol{\beta}^{(j)}$.
Similarly, the weak derivative $D^{\boldsymbol{\sigma}}_{\bold{P}} \nabla(e^F)$ exists in $\Sigma_{\boldsymbol{\sigma}}^c$ and the gradient of the general term (\ref{dp_ef}) is equal to
\begin{equation}
\label{ddp_ef}
e^F \, \nabla F \prod_{1 \le j \le n} D_{\bold{P}}^{\boldsymbol{\beta}^{(j)}}F + e^F \sum_{r=1}^n \Big(D_{\bold{P}}^{\boldsymbol{\beta}^{(r)}} \nabla F\, \prod_{\substack{1\le j \le n \\ j\ne r}} D_{\bold{P}}^{\boldsymbol{\beta}^{(j)}} F\Big).
\end{equation}
We will now find bounds for the above expressions. To do this we will use (\ref{dd_f}) to bound cluster derivatives of $F$. This, along with (\ref{mu_1sig}) and (\ref{lam_prod}) of Lemma \ref{mu_lemma}, allows us to bound the following product
\begin{align*}

\Big|\prod_{j=1}^n D_{\bold{P}}^{\boldsymbol{\beta}^{(j)}} F (\bold{y})\Big| &\le C \prod_{j=1}^n \mu_{\boldsymbol{\beta}^{(j)}}(\bold{y})^{1-|\boldsymbol{\beta}^{(j)}|}\\

&\le C \prod_{j=1}^n  \lambda_{\boldsymbol{\beta}^{(j)}}(\bold{y}) \lambda_{P_1}(\bold{y})^{-|\beta^{(j)}_1|} \dots \lambda_{P_M}(\bold{y})^{-|\beta^{(j)}_M|} \\

&= C \Big(\prod_{j=1}^n  \lambda_{\boldsymbol{\beta}^{(j)}}(\bold{y})\Big) \Big( \prod_{l=1}^M \lambda_{P_l}(\bold{y})^{-|\beta^{(1)}_l|} \dots \lambda_{P_l}(\bold{y})^{-|\beta^{(n)}_l|}\Big) \\

&\le C\lambda_{\boldsymbol{\sigma}}(\bold{y}) \lambda_{P_1}(\bold{y})^{-|\sigma_1|} \dots \lambda_{P_M}(\bold{y})^{-|\sigma_M|}
\end{align*}
where $C$ is some constant, depending on $\boldsymbol{\sigma}$, and all $\bold{y} \in \Sigma^c_{\boldsymbol{\sigma}}$. We used that for each $l=1,\dots,M$, we have $|\beta^{(1)}_l| + \dots + |\beta^{(n)}_l| = |\sigma_l|$ as a consequence of $\boldsymbol{\beta}^{(1)} + \dots + \boldsymbol{\beta}^{(n)} = \boldsymbol{\sigma}$. We now bound the following product in a similar manner using (\ref{dd_f}) and Lemma \ref{mu_lemma}. For any $r=1, \dots, n$,
\begin{align*}

\Big| D^{\boldsymbol{\beta}^{(r)}}_{\bold{P}} \nabla F(\bold{y}) \prod_{\substack{1\le j\le n \\ j \ne r}} D^{\boldsymbol{\beta}^{(j)}}_{\bold{P}} F(\bold{y}) \Big| &\le C \lambda_{P_1}(\bold{y})^{-|\sigma_1|} \dots \lambda_{P_M}(\bold{y})^{-|\sigma_M|}
\end{align*}
for some constant $C$, depending on $\boldsymbol{\sigma}$, and all $\bold{y} \in \Sigma^c_{\boldsymbol{\sigma}}$. Using the fact that $e^F$ and $\nabla F$ are bounded in $\mathbb{R}^{3N}$, it is now straightforward to bound (\ref{dp_ef}) and (\ref{ddp_ef}) appropriately. This completes the proof of (\ref{dd_f_ef}).


\paragraph{}

Finally, we prove the inequality (\ref{dd_f_2}). It can be shown that the following Leibniz rule holds

\begin{equation*}
D_{\bold{P}}^{\boldsymbol{\sigma}} |\nabla F|^2 = \sum_{\boldsymbol{\beta} \le \boldsymbol{\sigma}} {\boldsymbol{\sigma} \choose \boldsymbol{\beta}} D^{\boldsymbol{\beta}}_{\bold{P}} \nabla F \cdot D^{\boldsymbol{\sigma}-\boldsymbol{\beta}}_{\bold{P}} \nabla F
\end{equation*}
in $\Sigma^c_{\boldsymbol{\sigma}}$. For every $\boldsymbol{\beta} \le \boldsymbol{\sigma}$ we can bound $D^{\boldsymbol{\beta}}_{\bold{P}} \nabla F$ by a constant if $\boldsymbol{\beta} = 0$, and by (\ref{dd_f}) otherwise. This gives some constant $C$, depending on $\boldsymbol{\sigma}$, such that
\begin{align*}
\big|D_{\bold{P}}^{\boldsymbol{\sigma}} |\nabla F(\bold{y})|^2\big| &\le C\sum_{\boldsymbol{\beta} \le \boldsymbol{\sigma}}  \mu_{\boldsymbol{\beta}}(\bold{y})^{-|\boldsymbol{\beta}|} \mu_{\boldsymbol{\sigma} - \boldsymbol{\beta}}(\bold{y})^{-|\boldsymbol{\sigma}|+|\boldsymbol{\beta}|}
\end{align*}
for all $\bold{y} \in \Sigma^c_{\boldsymbol{\sigma}}$. The required bound is obtained after an application of (\ref{mu_1sig}) of Lemma \ref{mu_lemma}.

\label{ab_lem}
For any $|\boldsymbol\sigma| \ge 1$ and any $\nu \in (0,1)$ there exists $C$, depending on $\boldsymbol{\sigma}$ and $\nu$, such that for $k=0,1$,
\begin{multline}
\label{dd_f_ef_2}
\left\lVertD_{\bold{P}}^{\boldsymbol{\sigma}} \nabla^k F\right\rVert_{L^{\infty}(B(\bold{x}, \nu\lambda_{\boldsymbol{\sigma}}(\bold{x})))},\, \left\lVertD_{\bold{P}}^{\boldsymbol{\sigma}}  \nabla^k (e^F)\right\rVert_{L^{\infty}(B(\bold{x}, \nu\lambda_{\boldsymbol{\sigma}}(\bold{x})))}\\ \le C\lambda_{\boldsymbol{\sigma}}(\bold{x})^{1-k} \lambda_{P_1}(\bold{x})^{-|\sigma_1|} \dots \lambda_{P_M}(\bold{x})^{-|\sigma_M|}
\end{multline}
\begin{equation}
\label{dd_f_2_2}
\left\lVertD_{\bold{P}}^{\boldsymbol{\sigma}} |\nabla F|^2\right\rVert_{L^{\infty}(B(\bold{x}, \nu\lambda_{\boldsymbol{\sigma}}(\bold{x})))} \le C\lambda_{P_1}(\bold{x})^{-|\sigma_1|} \dots \lambda_{P_M}(\bold{x})^{-|\sigma_M|}
\end{equation}
for all $\bold{x} \in \Sigma_{\boldsymbol{\sigma}}^c$. The bound to the first norm in (\ref{dd_f_ef_2}) also holds when $F$ is replaced by $F_c$.

Take some $\bold{x} \in \Sigma_{\boldsymbol{\sigma}}^c$. By (\ref{lam_lip}), for each $\bold{y} \in B(\bold{x}, \nu\lambda_{\boldsymbol{\sigma}}(\bold{x}))$ we have
\begin{equation*}
|\lambda_{P_j}(\bold{x}) - \lambda_{P_j}(\bold{y})| \le |\bold{x} - \bold{y}| \le \nu \lambda_{\boldsymbol{\sigma}}(\bold{x}) \le \nu \lambda_{P_j}(\bold{x})
\end{equation*}
for each $j=1, \dots, M$ with $\sigma_j \ne 0$. The final inequality above uses the definition of $\lambda_{\boldsymbol{\sigma}}$ in (\ref{eq:lam_alpha}). By rearrangement, we have
\begin{equation}
\label{lam_xy_eq}
(1-\nu)\lambda_{P_j}(\bold{x}) \le \lambda_{P_j}(\bold{y}).
\end{equation}
Therefore,
\begin{equation}
\label{lamlam1}
\lambda_{P_1}(\bold{y})^{-|\sigma_1|} \dots \lambda_{P_M}(\bold{y})^{-|\sigma_M|} \le (1-\nu)^{-|\boldsymbol{\sigma}|} \lambda_{P_1}(\bold{x})^{-|\sigma_1|} \dots \lambda_{P_M}(\bold{x})^{-|\sigma_M|}
\end{equation}
for all $\bold{y} \in B(\bold{x}, \nu\lambda_{\boldsymbol{\sigma}}(\bold{x}))$. We now prove an analogous inequality. First, we see that $\lambda_{\boldsymbol{\sigma}}(\bold{x}) = \lambda_{P_l}(\bold{x})$ for some $1 \le l \le M$ with $\sigma_l \ne 0$ which will depend on the choice of $\bold{x}$. We also note that $\lambda_{\boldsymbol{\sigma}}(\bold{y}) \le \lambda_{P_l}(\bold{y})$ for all $\bold{y} \in \mathbb{R}^{3N}$ which follows from $\sigma_l \ne 0$ and the definition of $\lambda_{\boldsymbol{\sigma}}$. Therefore,
\begin{align}
\nonumber
\lambda_{\boldsymbol{\sigma}}(\bold{y})\lambda_{P_1}(\bold{y})^{-|\sigma_1|} \dots \lambda_{P_M}(\bold{y})^{-|\sigma_M|}
&\le  \lambda_{P_l}(\bold{y})^{1-|\sigma_l|}\prod_{\substack{j=1 \\ j \ne l}}^M \lambda_{P_j}(\bold{y})^{-|\sigma_j|}\\
\nonumber
&\le (1-\nu)^{1-|\boldsymbol{\sigma}|} \lambda_{P_l}(\bold{x})^{1-|\sigma_l|}\prod_{\substack{j=1 \\ j \ne l}}^M \lambda_{P_j}(\bold{x})^{-|\sigma_j|}\\
\label{lamlam2}
&= (1-\nu)^{1-|\boldsymbol{\sigma}|} \lambda_{\boldsymbol{\sigma}}(\bold{x}) \lambda_{P_1}(\bold{x})^{-|\sigma_1|} \dots \lambda_{P_M}(\bold{x})^{-|\sigma_M|}
\end{align}
for all $\bold{y} \in B(\bold{x}, \nu\lambda_{\boldsymbol{\sigma}}(\bold{x}))$. In the second step we applied (\ref{lam_xy_eq}). The required bounds then arise from Lemma \ref{der_gradF} followed by either (\ref{lamlam1}) or (\ref{lamlam2}) as appropriate.

\label{diff_pde_lem}
For every $| oldsymbol\alpha| \ge 1$ we have $\phi_{ oldsymbol{\alpha}}$ is a weak solution to
 egin{multline}
\label{phi_alpha_eq}
-\Delta \phi_{ oldsymbol{\alpha}} - 2
abla F \cdot 
