\end{multline}
in $\Sigma^c_{ oldsymbol\alpha}$, and therefore $\phi_{ oldsymbol{\alpha}} \in C^1(\Sigma_{ oldsymbol\alpha}^c) \cap H^2_{loc}(\Sigma_{ oldsymbol\alpha}^c)$.

We prove by induction, starting with $|\boldsymbol{\alpha}| = 1$. Let $\mathcal{L}(\cdot,\cdot)$ be the bilinear form corresponding to the operator acting on $\phi_{\boldsymbol{\alpha}}$ on the left-hand side of (\ref{phi_alpha_eq}), as defined in (\ref{eq:pde}). Since $\phi \in H^{2}_{loc}(\mathbb{R}^{3N})$ we have $\phi_{\boldsymbol{\alpha}} \in H^1_{loc}(\mathbb{R}^{3N})$. We use integration by parts to show that, for any $\chi \in C^{\infty}_c(\Sigma^c_{\boldsymbol\alpha})$,
\begin{equation}
\label{eq:l_phi}
\mathcal{L}(\phi_{\boldsymbol{\alpha}} , \chi) = -\mathcal{L}(\phi, D_{\bold{P}}^{\boldsymbol{\alpha}}\chi) +  \int_{\Sigma^c_{\boldsymbol\alpha}} g_{\boldsymbol{\alpha}} \chi\,d\bold{x}.
\end{equation}
Now, $\mathcal{L}(\phi, D_{\bold{P}}^{\boldsymbol{\alpha}}\chi) = 0$ since $\phi$ is a weak solution to (\ref{phi_pde_eq}), hence (\ref{phi_alpha_eq}) holds. By Lemma \ref{der_gradF} and that $\phi \in C^1(\mathbb{R}^{3N})$ we see that $g_{\boldsymbol\alpha} \in L_{loc}^{\infty}(\Sigma^c_{\boldsymbol\alpha})$. Hence, by Theorems \ref{thm:c1}, $\phi_{\boldsymbol\alpha} \in C^1(\Sigma^c_{\boldsymbol\alpha}) \cap H_{loc}^2(\Sigma^c_{\boldsymbol\alpha})$


Assume the hypothesis holds for all multiindices $1 \le |\boldsymbol{\alpha}| \le k-1$ for some $k\ge 2$. Take some arbitrary multiindex $|\boldsymbol{\alpha}| = k$. We will prove the induction hypothesis for $\boldsymbol\alpha$. First, we state the useful fact that for any $\boldsymbol\sigma \le \boldsymbol\alpha$ we have $\Sigma_{\boldsymbol\sigma} \subset \Sigma_{\boldsymbol\alpha}$. Take some $\boldsymbol{\eta} \le \boldsymbol\alpha$ with $|\boldsymbol{\eta}| = 1$. Notice, then, that $\phi_{\boldsymbol\alpha-\boldsymbol{\eta}} \in H^2_{loc}(\Sigma^c_{\boldsymbol\alpha})$ by the induction hypothesis, and hence $\phi_{\boldsymbol{\alpha}} \in H^1_{loc}(\Sigma^c_{\boldsymbol\alpha})$. This allows $\mathcal{L}(\phi_{\boldsymbol\alpha}, \chi)$ to be defined for any $\chi \in C_c^{\infty}(\Sigma^c_{\boldsymbol\alpha})$. Integration by parts is then used on the $D^{\boldsymbol{\eta}}_{\bold{P}}$-derivative, in a similar way to (\ref{eq:l_phi}). Along with the induction hypothesis and further applications of integration by parts, we find that (\ref{phi_alpha_eq}) holds for $\phi_{\boldsymbol\alpha}$ as a weak solution. Regularity for $\phi_{\boldsymbol\alpha}$ is shown in a similar way to the $|\boldsymbol\alpha|=1$ case. Indeed, the induction hypothesis can be used to show $g_{\boldsymbol\alpha} \in L^{\infty}_{loc}(\Sigma^c_{\boldsymbol\alpha})$.

\label{er_phi_lem}
For all $|\boldsymbol{\alpha}| \ge 1$ and $0<r<R<1$ there exists $C$, dependent only on $E, Z, N, r$ and $R$, such that

\begin{multline}
\label{er_phi_eq}
\left\lVert\nabla \phi_{\boldsymbol{\alpha}}\right\rVert_{L^{\infty}(B(\bold{x}, r\lambda_{\boldsymbol{\alpha}}(\bold{x})))} \\\le C \lambda_{\boldsymbol{\alpha}}(\bold{x})^{-1} \big(\left\lVert\phi_{\boldsymbol{\alpha}}\right\rVert_{L^{\infty}(B(\bold{x}, R\lambda_{\boldsymbol{\alpha}}(\bold{x})))} + \lambda_{\boldsymbol{\alpha}}(\bold{x})^2 \left\lVertg_{\boldsymbol{\alpha}}\right\rVert_{L^{\infty}(B(\bold{x}, R\lambda_{\boldsymbol{\alpha}}(\bold{x})))} \big)
\end{multline}

for all $\bold{x} \in \Sigma_{\boldsymbol{\alpha}}^c$. The function $g_{\boldsymbol{\alpha}}$ was given by (\ref{phi_alpha_eq}).

Fix any $\bold{x} \in \Sigma_{\boldsymbol{\alpha}}^c$ and denote $\lambda = \lambda_{\boldsymbol{\alpha}}(\bold{x})$. The proof proceeds via a rescaling. Define
\begin{equation*}
\begin{split}
w(\bold{y}) &= \phi_{\boldsymbol{\alpha}}(\bold{x} + \lambda \bold{y})\\
\bold{c}(\bold{y}) &= -2\nabla F(\bold{x} + \lambda \bold{y})\\
d(\bold{y}) &= \Delta F_s(\bold{x} + \lambda \bold{y}) - |\nabla F (\bold{x} + \lambda \bold{y})|^2 - E \\
f(\bold{y}) &= g_{\boldsymbol{\alpha}}(\bold{x} + \lambda \bold{y})
\end{split}
\end{equation*}
for all $\bold{y} \in B(0,1)$. Then by Lemma \ref{diff_pde_lem} we have that $w$ is a weak solution to
\begin{equation}
\label{rescaled_pde}
-\Delta w + \lambda \bold{c} \cdot \nabla w + \lambda^2 d w = \lambda^2 f
\end{equation}
in $B(0,1)$. By (\ref{f_linf}) and (\ref{f2_linf}), and that $\lambda \le 1$ by definition, we obtain
\begin{equation*}
\lambda \left\lVert\bold{c}\right\rVert_{L^{\infty}(B(0,1))} + \lambda^2 \left\lVertd\right\rVert_{L^{\infty}(B(0,1))} \le K
\end{equation*}
for some $K$, dependent only on $E, Z$ and $N$ and in particular is independent of our choice of $\bold{x}$. Therefore, by Theorem \ref{thm:c1}, with $\theta=0$, we get some $C$, dependent only on $N, K, r$ and $R$, such that

\begin{equation}
\label{w_c1_eq}
\left\lVertw\right\rVert_{C^1(\overline{B(0,r)})} \le C(\left\lVertw\right\rVert_{L^{\infty}(B(0,R))} + \lambda^2 \left\lVertf\right\rVert_{L^{\infty}(B(0,R))}).
\end{equation}

Finally, we use $\nabla w(\bold{y}) = \lambda \nabla \phi_{\boldsymbol{\alpha}}(\bold{x} + \lambda \bold{y})$ by the chain rule, and rewrite (\ref{w_c1_eq}) to give (\ref{er_phi_eq}).

\label{dd_phi_prop}
For any $|\boldsymbol\alpha| \ge 1$, any $0<r<R<1$ and any $0 \le b < 1$ there exists $C$, dependent on $\boldsymbol\alpha, r, R$ and $b$, such that for $k=0,1$, with $k+|\boldsymbol\alpha| \ge 2$,
\begin{align*}

\left\lVert\nabla^k \phi_{\boldsymbol{\alpha}}\right\rVert_{L^{\infty}(B(\bold{x}, r\lambda_{\boldsymbol{\alpha}}(\bold{x})))} &\le C \lambda_{\boldsymbol{\alpha}}(\bold{x})^{1-k} \lambda_{P_1}(\bold{x})^{-|\alpha_1|} \dots \lambda_{P_M}(\bold{x})^{-|\alpha_M|} \mu_{\boldsymbol\alpha}(\bold{x})^{b} f_{\infty}(\bold{x}; R; \phi )
\end{align*}
for all $\bold{x} \in \Sigma_{\boldsymbol{\alpha}}^c$. The inequality also holds for $|\boldsymbol\alpha|=1$ and $k=0$ if we take $b=0$.

Suppose $|\boldsymbol\alpha| = 1$ and $k=1$. Let $l$ be the index $1 \le l \le M$ such that $\alpha_l \ne 0$. Then $\mu_{\boldsymbol\alpha} = \lambda_{P_l}$ and $\Sigma_{\boldsymbol\alpha} = \Sigma_{P_l}$.                                                                                                 
The bound then follows from Corollary \ref{cor:d2phi} with $P=P_l$. Indeed, for each $s>0$ we can find some constant $C_s$ such that $\log(t) \le C_st^s$ for all $t >0$. We use this fact along with the simple inequality $\lambda_{P_l} \le \nu_{P_l}$.

For $|\boldsymbol\alpha| \ge 2$ we prove by induction. 

Assume the hypothesis holds for all multiindices $\boldsymbol{\alpha}$ with $1 \le |\boldsymbol{\alpha}| \le m-1$ for some $m \ge 2$. Take any $\boldsymbol{\alpha}$ with $|\boldsymbol{\alpha}| = m$. We prove the $k=0$ and $k=1$ cases in turn. It is useful, here, to state the following fact: for all $\boldsymbol{\sigma} \le \boldsymbol{\alpha}$ we have $\Sigma_{\boldsymbol{\sigma}} \subset \Sigma_{\boldsymbol{\alpha}}$ and hence $\lambda_{\boldsymbol{\alpha}}(\bold{x}) \le \lambda_{\boldsymbol{\sigma}}(\bold{x})$.


The $k=0$ case is a straightforward application of the induction hypothesis and is described as follows.                                                                                                                                 
Firstly, for each $\mathbf x \in \Sigma_{\boldsymbol\alpha}^c$ it is clear that there exists some $1 \le l \le M$ such that $\lambda_{\boldsymbol\alpha}(\bold{x}) = \lambda_{P_l}(\bold{x})$ and where $\alpha_l \ne 0$. Therefore we can find some $\boldsymbol{\eta} \le \boldsymbol\alpha$ with $|\boldsymbol{\eta}| = 1$ and $\eta_j = 0$ for each $j \ne l$ where $1 \le j \le M$. Now, from the definition of cluster derivatives (\ref{eq:cd2}),
\begin{align}
\label{ua_bound}
\left\lVert\phi_{\boldsymbol\alpha}\right\rVert_{L^{\infty}(B(\bold{x}, r\lambda_{\boldsymbol\alpha}(\bold{x})))} &\le N\left\lVert\nabla \phi_{\boldsymbol\alpha-\boldsymbol{\eta}}\right\rVert_{L^{\infty}(B(\bold{x}, r\lambda_{\boldsymbol{\alpha}}(\bold{x})))}.
\end{align}
We can then use the induction assumption to show existence of $C$ such that
\begin{multline}
\label{du_ae_bound}
\left\lVert\nabla \phi_{\boldsymbol\alpha-\boldsymbol{\eta}}\right\rVert_{L^{\infty}(B(\bold{x}, r\lambda_{\boldsymbol{\alpha}}(\bold{x})))} \\\le C \lambda_{P_l}(\bold{x}) \lambda_{P_1}(\bold{x})^{-|\alpha_1|} \dots \lambda_{P_M}(\bold{x})^{-|\alpha_M|}\mu_{\boldsymbol\alpha-\boldsymbol{\eta}}(\bold{x})^{b} f_{\infty}(\bold{x}; R; \phi),   

\end{multline}
where we can then use $\lambda_{P_l}(\bold{x}) = \lambda_{\boldsymbol{\alpha}}(\bold{x}) $ and  $\mu_{\boldsymbol\alpha-\boldsymbol{\eta}}(\bold{x}) \le \mu_{\boldsymbol\alpha}(\bold{x})$ to complete the required bound for our choice of $\boldsymbol\alpha$ in the case of $k=0$. 

The $k=1$ case follows from the induction hypothesis and Lemma \ref{er_phi_lem}. Let $r' = (r+R)/2$.
Firstly, by the definition of $g_{\boldsymbol\alpha}$, (\ref{phi_alpha_eq}), along with (\ref{f2_linf}) and Lemma \ref{ab_lem} we can find $C$, depending on $\boldsymbol\alpha$ and $r'$, such that
\begin{multline*}
\left\lVertg_{\boldsymbol\alpha}\right\rVert_{L^{\infty}(B(\bold{x}, r'\lambda_{\boldsymbol{\alpha}}(\bold{x})))}
\le C \sum_{\substack{\boldsymbol{\sigma} \le \boldsymbol{\alpha} \\ \boldsymbol{\sigma} \ne 0}} \lambda_{P_1}(\bold{x})^{-|\sigma_1|} \dots \lambda_{P_M}(\bold{x})^{-|\sigma_M|}\big(\left\lVert\phi_{\boldsymbol{\alpha}-\boldsymbol{\sigma}}\right\rVert_{L^{\infty}(B(\bold{x}, r'\lambda_{\boldsymbol{\alpha}}(\bold{x})))}\\+ \left\lVert\nabla \phi_{\boldsymbol{\alpha}-\boldsymbol{\sigma}}\right\rVert_{L^{\infty}(B(\bold{x}, r'\lambda_{\boldsymbol{\alpha}}(\bold{x})))}\big).
\end{multline*}
It follows by the induction hypothesis, using $b=0$, along with the definition of $f_{\infty}$, (\ref{eq:f_inf}), that we can find some $C$, depending on $\boldsymbol\alpha, r'$ and $R$, such that
\begin{equation}
\label{eq:ga_linf}
\left\lVertg_{\boldsymbol{\alpha}}\right\rVert_{L^{\infty}(B(\bold{x}, r'\lambda_{\boldsymbol{\alpha}}(\bold{x})))}
\le C \lambda_{P_1}(\bold{x})^{-|\alpha_1|} \dots \lambda_{P_M}(\bold{x})^{-|\alpha_M|} f_{\infty}(\bold{x}; R; \phi)
\end{equation}
for all $\bold{x} \in \Sigma_{\boldsymbol\alpha}^c$. Next, we apply Lemma \ref{er_phi_lem} to obtain some constant $C$, depending on $r$ and $r'$, such that
\begin{align*}
\left\lVert\nabla \phi_{\boldsymbol{\alpha}}\right\rVert_{L^{\infty}(B(\bold{x}, r\lambda_{\boldsymbol{\alpha}}(\bold{x})))} &\le C\big( \lambda_{\boldsymbol\alpha}(\bold{x})^{-1}\left\lVert\phi_{\boldsymbol\alpha}\right\rVert_{L^{\infty}(B(\bold{x}, r'\lambda_{\boldsymbol\alpha}(\bold{x})))} + \lambda_{\boldsymbol{\alpha}}(\bold{x}) \left\lVertg_{\boldsymbol{\alpha}}\right\rVert_{L^{\infty}(B(\bold{x}, r'\lambda_{\boldsymbol{\alpha}}(\bold{x})))} \big).   

\end{align*}

We use the $k=0$ case, proven above, to bound the $L^{\infty}$-norm of $\phi_{\boldsymbol\alpha}$ in the first term on the right-hand side of the above inequality. To the second term, we apply (\ref{eq:ga_linf}) and the simple inequality $\lambda_{\boldsymbol\alpha}(\bold{x}) \le \mu_{\boldsymbol\alpha}(\bold{x})$. Together, these give the required bound for $k=1$ and our choice of $\boldsymbol\alpha$. This completes the induction.

It is clear that (\ref{eq:ddpsi}) holds when $\boldsymbol\alpha = 0$. Therefore, consider $|\boldsymbol\alpha| \ge 1$. We first prove (\ref{eq:ddpsi}) for $k=0$. Take $\bold{x} \in \Sigma_{\boldsymbol\alpha}^c$, then by the Leibniz rule for cluster derivatives we have
\begin{align}
\label{eq:psi_leibniz}
D_{\bold{P}}^{\boldsymbol{\alpha}}\psi &= \sum_{\boldsymbol{\beta} \le \boldsymbol{\alpha}} {\boldsymbol{\alpha} \choose \boldsymbol{\beta} } D_{\bold{P}}^{\boldsymbol{\beta}}\big(e^F \big) \phi_{\boldsymbol{\alpha}-\boldsymbol{\beta}}
\end{align}
in $B(\bold{x}, r\lambda_{\boldsymbol\alpha}(\bold{x}))$. Now, for each $\boldsymbol{\beta} \le \boldsymbol{\alpha}$ there exists some $C$, independent of $\mathbf x$, such that

\begin{equation*}
\left\lVertD_{\bold{P}}^{\boldsymbol{\beta}}\big(e^F \big) \phi_{\boldsymbol{\alpha}-\boldsymbol{\beta}}\right\rVert_{L^{\infty}(B(\bold{x}, r\lambda_{\boldsymbol{\alpha}}(\bold{x})))} \le C\lambda_{\boldsymbol\alpha}(\bold{x}) \lambda_{P_1}(\bold{x})^{-|\alpha_1|} \dots \lambda_{P_M}(\bold{x})^{-|\alpha_M|} f_{\infty}(\bold{x}; R; \phi).
\end{equation*}
To prove this, we use Lemma \ref{ab_lem} and Proposition \ref{dd_phi_prop} with $b=0$. In addition, if $\boldsymbol\beta = 0$ we use (\ref{f_linf}) and if $\boldsymbol\beta = \boldsymbol\alpha$ we use the definition (\ref{eq:f_inf}). If $\boldsymbol\beta \notin \{0, \boldsymbol\alpha \}$ we use the inequality $\lambda_{\boldsymbol{\beta}}(\bold{x}) \lambda_{\boldsymbol{\alpha}-\boldsymbol{\beta}}(\bold{x}) \le \lambda_{\boldsymbol{\alpha}}(\bold{x})$, which is obtained from Lemma \ref{mu_lemma}. The required bound (\ref{eq:ddpsi}) for $k=0$ then follows from (\ref{eq:psi_leibniz}) and (\ref{eq:phi_er})-(\ref{eq:phi_psi}).

Take $\mathbf x \in \Sigma^c_{\boldsymbol\alpha}$. By the definition $F= F_c - F_s$, the equality $\nabla \psi = \psi \nabla F + e^F \nabla \phi$ and the Leibniz rule, we have (\ref{eq:gp_def}) with
\begin{align}
\label{eq:gp_def_full}
G^{\boldsymbol\alpha}_{\bold{P}} &= \sum_{\substack{\boldsymbol\beta \le \boldsymbol\alpha \\ |\boldsymbol\beta| \ge 1}} {\boldsymbol{\alpha} \choose \boldsymbol{\beta} } D_{\bold{P}}^{\boldsymbol\beta}\psi\, D_{\bold{P}}^{\boldsymbol\alpha - \boldsymbol\beta}\nabla F +
\sum_{\boldsymbol\beta \le \boldsymbol\alpha} {\boldsymbol{\alpha} \choose \boldsymbol{\beta}} \nabla \phi_{\boldsymbol\beta}\, D_{\bold{P}}^{\boldsymbol\alpha - \boldsymbol\beta} \big(e^F \big) - \psi\, D_{\bold{P}}^{\boldsymbol\alpha}\nabla F_s.
\end{align}

We bound each term in $G^{\boldsymbol\alpha}_{\bold{P}}$ as in (\ref{eq:gp_bnd}).
Take any $\boldsymbol\beta \le \boldsymbol\alpha$ with $|\boldsymbol\beta| \ge 1$. Notice that $\Sigma_{\boldsymbol\beta} \subset \Sigma_{\boldsymbol\alpha}$ and hence $\lambda_{\boldsymbol\alpha}(\mathbf x) \le \lambda_{\boldsymbol\beta}(\mathbf x)$. Now, there exists $C$, independent of $\mathbf x$, such that
\begin{align}
\label{eq:gp_term1}
\left\lVertD_{\bold{P}}^{\boldsymbol\beta}\psi\, D_{\bold{P}}^{\boldsymbol\alpha -\boldsymbol\beta} \nabla F \right\rVert_{L^{\infty}(B(\bold{x}, r\lambda_{\boldsymbol{\alpha}}(\bold{x})))} &\le C\lambda_{\boldsymbol\beta}(\bold{x}) \lambda_{P_1}(\bold{x})^{-|\alpha_1|} \dots \lambda_{P_M}(\bold{x})^{-|\alpha_M|} f_{\infty}(\bold{x}; R).
\end{align}
To prove this inequality, we bound derivatives of $F$ using Lemma \ref{ab_lem} if $\boldsymbol\beta \ne \boldsymbol\alpha$ and (\ref{f_linf}) if $\boldsymbol\beta = \boldsymbol\alpha$. The derivatives $D_{\bold{P}}^{\boldsymbol\beta}\psi$ are then bounded using (\ref{eq:ddpsi}) with $k=0$, which was proven above. The right-hand side of (\ref{eq:gp_term1}) can be bounded as in (\ref{eq:gp_bnd}) by using the simple bound $\lambda_{\boldsymbol\beta} \le \mu_{\boldsymbol\alpha}$.  Next, still considering $|\boldsymbol\beta| \ge 1$ we can find $C$, independent of $\mathbf x$, such that
\begin{align*}
\left\lVert \nabla \phi_{\boldsymbol\beta}\, D_{\bold{P}}^{\boldsymbol\alpha - \boldsymbol\beta} \big(e^F \big) \right\rVert_{L^{\infty}(B(\bold{x}, r\lambda_{\boldsymbol{\alpha}}(\bold{x})))} &\le C\mu_{\boldsymbol\beta}(\bold{x})^b \lambda_{\boldsymbol\alpha - \boldsymbol\beta}(\bold{x}) \lambda_{P_1}(\bold{x})^{-|\alpha_1|} \dots \lambda_{P_M}(\bold{x})^{-|\alpha_M|} f_{\infty}(\bold{x}; R; \phi).
\end{align*}
This is proven using Proposition \ref{dd_phi_prop} to bound the derivatives $\nabla \phi_{\boldsymbol\beta}$, and Lemma \ref{ab_lem} and (\ref{f_linf}) to bound derivatives of $e^F$. The right-hand side of the above inequality can be bounded as in (\ref{eq:gp_bnd}) after use of (\ref{eq:phi_er})-(\ref{eq:phi_psi}) and the inequalities $\mu_{\boldsymbol\beta} \le \mu_{\boldsymbol\alpha}$ and $\lambda_{\boldsymbol\alpha - \boldsymbol\beta} \le 1$. 
In addition, by Lemma \ref{ab_lem} there exists $C$ such that
\begin{align*}
\left\lVert \nabla \phi\, D_{\bold{P}}^{\boldsymbol\alpha} \big(e^F \big) \right\rVert_{L^{\infty}(B(\bold{x}, r\lambda_{\boldsymbol{\alpha}}(\bold{x})))} &\le C\lambda_{\boldsymbol\alpha}(\bold{x}) \lambda_{P_1}(\bold{x})^{-|\alpha_1|} \dots \lambda_{P_M}(\bold{x})^{-|\alpha_M|} f_{\infty}(\bold{x}; R; \phi).
\end{align*}
Use of (\ref{eq:phi_er})-(\ref{eq:phi_psi}), as before, and the inequality $\lambda_{\boldsymbol\alpha} \le \mu_{\boldsymbol\alpha}$ give the correct bound. Finally, the last term in (\ref{eq:gp_def_full}) is readily bounded appropriately using (\ref{f2_linf}). In view of (\ref{eq:gp_def_full}), this completes the proof of (\ref{eq:gp_bnd}).

To prove (\ref{eq:ddpsi}) for $k=1$ we use (\ref{eq:gp_def}), (\ref{eq:gp_bnd}) and the following inequality,
\begin{equation*}
\left\lVert\psi D_{\bold{P}}^{\boldsymbol\alpha}\nabla F_c\right\rVert_{L^{\infty}(B(\bold{x}, r\lambda_{\boldsymbol{\alpha}}(\bold{x})))} \le C\lambda_{P_1}(\bold{x})^{-|\alpha_1|} \dots \lambda_{P_M}(\bold{x})^{-|\alpha_M|} f_{\infty}(\bold{x}; R)
\end{equation*}
which holds for some $C$ as a direct consequence of Lemma \ref{ab_lem}.

\label{pou}
There exists a collection $\{\Phi^{(j)} \}_{j=1}^{J}$ of cutoffs (\ref{eq:pphi_def}), with integer $J$ depending only on $N$, such that whenever $0< 2\delta \le \epsilon$ we have
\begin{equation*}
\sum_{j=1}^{J} \Phi^{(j)}(x,y,\bold{\hat{x}}) = 1
\end{equation*}
for all $x,y \in \mathbb{R}^3$, $\bold{\hat{x}} \in \mathbb{R}^{3N-3}$.

From the definitions (\ref{cutoff_factors}) and support criteria it is straightforward to verify that








\begin{align}
\theta_{\delta}(z)\theta_{\epsilon}(z) = \theta_{\epsilon}(z), \qquad
\zeta_{\delta}(z)\theta_{\epsilon}(z) = 0, \qquad
\zeta_{\delta}(z)\zeta_{\epsilon}(z) = \zeta_{\delta}(z)
\end{align}
for all $z \in \mathbb{R}^3$. It follows that on $\mathbb{R}^3$,
\begin{equation}
1 \equiv \big(\zeta_{\delta} + \theta_{\delta}\big) \big(\zeta_{\epsilon} + \theta_{\epsilon}\big) = \zeta_{\delta} + \theta_{\delta}\zeta_{\epsilon} + \theta_{\epsilon}.
\end{equation}


\paragraph{}
For any $A,B \subset \{2, \dots, N \}$ with $A \cap B = \emptyset$ we define
\begin{equation*}
\tau_{A,B}(\bold{x}) = \prod_{j \in A} \zeta_{\delta}(x_1-x_j) \prod_{j \in B}(\theta_{\delta}\zeta_{\epsilon})(x_1-x_j) \prod_{j\in \{2,\dots,N\}\backslash(A\cup B)} \theta_{\epsilon}(x_1-x_j)
\end{equation*}

for $\bold{x} = (x_1, \dots, x_N) \in \mathbb{R}^{3N}$. Therefore,
\begin{equation*}
\sum_{\substack{A \subset \{2,\dots,N\} \\ B \subset \{2,\dots,N \}\backslash A}} \tau_{A,B}(\bold{x}) = \prod_{2 \le j \le N} \big\{\zeta_{\delta}(x_1-x_j) + (\theta_{\delta}\zeta_{\epsilon})(x_1-x_j) + \theta_{\epsilon}(x_1-x_j) \big\} = 1
\end{equation*}
for all $\bold{x} \in \mathbb{R}^{3N}$.

Let $\Xi = \{(j,k) : 2 \le j <k \le N \}$. For each $Y, Z \subset \Xi$ with $Y \cap Z = \emptyset$ we define
\begin{equation*}
T_{Y,Z}(\bold{\hat{x}}) =  \prod_{(j,k) \in Y} \zeta_{\delta}(x_j-x_k) \prod_{(j,k) \in Z}(\theta_{\delta}\zeta_{\epsilon})(x_j-x_k) \prod_{(j,k) \,\in\, \Xi\backslash(Y\cup Z)} \theta_{\epsilon}(x_j-x_k)
\end{equation*}

for $\bold{\hat{x}} = (x_2, \dots, x_N) \in \mathbb{R}^{3N-3}$. Therefore,
\begin{equation*}
\sum_{\substack{Y \,\subset\, \Xi \\ Z \,\subset\, \Xi\backslash Y}} T_{Y,Z}(\bold{\hat{x}}) = \prod_{2\le j<k \le N} \big(\zeta_{\delta}(x_j-x_k) + (\theta_{\delta}\zeta_{\epsilon})(x_j-x_k) + \theta_{\epsilon}(x_j-x_k) \big) = 1
\end{equation*}
for all $\bold{\hat{x}} \in \mathbb{R}^{3N-3}$. Overall, for all $x,y \in \mathbb{R}^3$, $\bold{\hat{x}} \in \mathbb{R}^{3N-3}$,
\begin{equation*}
\sum_{\substack{A \subset \{2,\dots,N\} \\ B \subset \{2,\dots,N\}\backslash A}} \quad \sum_{\substack{C \subset \{2,\dots,N\} \\ D \subset \{2,\dots,N\}\backslash C}} \quad \sum_{\substack{Y \,\subset\, \Xi \\ Z \,\subset\, \Xi\backslash Y}}   \tau_{A,B}(x, \bold{\hat{x}})  \tau_{C,D}(y, \bold{\hat{x}})  T_{Y,Z}(\bold{\hat{x}}) = 1,
\end{equation*}
which is a sum of cutoffs of the form (\ref{eq:pphi_def}).

\label{lem:support}
We have $\Phi(x,y,\bold{\hat{x}}) = 0$ unless
\begin{align}
\label{eq:lam_b1}
|x - x_k|,\,|y-x_k|,\, |x_j - x_k| &> (4N)^{-1}\epsilon \qquad &&j \in Q^*, k\in Q^c,\\
\label{eq:lam_b3}
|x -x_j|, |y -x_k| &> (4N)^{-1}\delta \quad &&j \in P^{c},\, k \in S^c,\\
\label{eq:lam_b4}
|x_r -x_s| &> (4N)^{-1}\delta \quad && r \in P^{*},\, s \in P^{c} \text{  or  } r \in S^{*},\, s \in S^{c}.
\end{align}

\label{particle_ineqs}
Let $0<2\delta \le \epsilon$. Then $\Phi(x,y,\hat{\bold{x}}) = 0$ unless
\begin{align}
|x-x_k| < \delta/2 \quad\text{ for }\quad k \in P^*,\\
|y-x_k| < \delta/2 \quad\text{ for }\quad k \in S^*,
\end{align} 
and if $|x-y| \ge \delta$ then $\Phi(x,y,\hat{\bold{x}}) = 0$ unless
\begin{align}
|y-x_k| > \delta/2 \quad\text{ for }\quad k \in P^*,\\
|x-x_k| > \delta/2 \quad\text{ for }\quad k \in S^*.
\end{align} 
Therefore, if $P^* \cap S^* \ne \emptyset$ then $\Phi(x,y,\bold{\hat{x}}) = 0$ for all $|x-y| \ge \delta$ and $\bold{\hat{x}} \in \mathbb{R}^{3N-3}$.

Furthermore, if $|x|,|y|\ge \epsilon$ then $\Phi(x,y,\hat{\bold{x}}) = 0$ unless
\begin{align}
\label{eq:particle_ineq3}
\min\{|x-x_k|,\, |y-x_k|\} < \epsilon/2 \quad\text{ for }\quad k \in Q^*,\\
\label{eq:lam_b2}
|x_k| > \epsilon/2 \quad\text{ for }\quad k \in Q^*.
\end{align}

By definition, if $k \in P^{*}$ either $g^{(1)}_k = \zeta_{\delta}$ or there exist pairwise distinct $j_1, \dots, j_s \in \{2,\dots,N\}$ with $1\le s \le N-2$ such that $g^{(1)}_{j_1} = \zeta_{\delta}$ and $f_{j_1,j_2}, f_{j_2, j_3}, \, \dots,\, f_{j_s, k} = \zeta_{\delta}$. In the former case, support criteria for $\zeta_{\delta}(x-x_k)$ gives $|x - x_k| < (2N)^{-1}\delta$. In the latter case, support conditions give $|x - x_{j_1}|,\, |x_{j_1} - x_{j_2}|,\, \dots,\, |x_{j_s} - x_k|  < (2N)^{-1}\delta$ and so by the triangle inequality $|x - x_k| < \delta/2$. Now, $|y-x_k| \ge |x-y|-|x-x_k| > \delta/2$ by the reverse triangle inequality. The case of $k \in S^*$ is analogous.

\paragraph{}
Now let $k \in Q^*$. First, we consider the case where either $g^{(1)}_k \ne \theta_{\epsilon}$ or $g^{(2)}_k \ne \theta_{\epsilon}$, or both. Without loss, assume $g^{(1)}_k \ne \theta_{\epsilon}$. Then either $g^{(1)}_k = \zeta_{\delta}$ or  $g^{(1)}_k = \theta_{\delta}\zeta_{\epsilon}$, but both give the inequality
\begin{equation*}
|x-x_k| < (2N)^{-1}\epsilon
\end{equation*} 
by support criteria. Hence (\ref{eq:particle_ineq3}) holds in this case.




Now suppose that $g^{(1)}_k = g^{(2)}_k = \theta_{\epsilon}$. Then there must exist pairwise distinct $j_1, \dots, j_s \in \{2,\dots,N\}$ with $1\le s \le N-2$ such that $f_{j_1,j_2}, f_{j_2,j_3},\dots,f_{j_s, k} \ne \theta_{\epsilon}$ and either $g^{(1)}_{j_1} \ne \theta_{\epsilon}$ or $g^{(2)}_{j_1} \ne \theta_{\epsilon}$. Without loss take $g^{(1)}_{j_1} \ne \theta_{\epsilon}$, so that, as before, $|x-x_{j_1}| < (2N)^{-1}\epsilon$. Similarly, we get $|x_{j_1} - x_{j_2}|,\, \dots,\, |x_{j_s} - x_k|  < (2N)^{-1}\epsilon$. Therefore, by the triangle inequality, $|x-x_k| < \epsilon/2$. Hence completing the proof of (\ref{eq:particle_ineq3}). Finally, (\ref{eq:lam_b2}) follows from (\ref{eq:particle_ineq3}) and $|x|,|y| \ge \epsilon$.

\label{phi_factors_lem}
Given a cutoff $\Phi$ of the form (\ref{eq:pphi_def}) and any cluster $T$ with $1 \in T$ we have
\begin{equation}
\label{phi_factors}
\Phi(x,y,\bold{\hat{x}}) =  \Phi(x,y,\bold{\hat{x}}; T)\Phi(x,y,\bold{\hat{x}};T,T^c)\Phi(x,y,\bold{\hat{x}}; T^c).
\end{equation}

This identity follows from the definitions (\ref{eq:pphi_t})-(\ref{eq:pphi_ttc}) and the equality
\begin{equation*}
\prod_{2 \le k<l \le N} f_{k,l}(x_k - x_l) = \prod_{\substack{k,l \in T^* \\ k < l}} f_{k,l}(x_k - x_l) \prod_{\substack{k \in T^* \\ l \in T^c}} f_{k,l}(x_k - x_l) \prod_{\substack{k,l \in T^c \\ k < l}} f_{k,l}(x_k - x_l),
\end{equation*}
since for any $2 \le k<l \le N$ we have $f_{k,l} = f_{l,k}$ by definition.

\label{lem:pphi_qqc}
For $Q = Q(\Phi)$,
\begin{equation}
\label{eq:phiqqc}
\Phi(x,y,\bold{\hat{x}}; Q,Q^c) =  \prod_{j \in Q^c} \theta_{\epsilon}(x - x_j) \prod_{j \in Q^c} \theta_{\epsilon}(y - x_j) \prod_{\substack{k \in Q^* \\ l \in Q^c}} \theta_{\epsilon}(x_k - x_l).
\end{equation}

\label{dcutoff_factors}
For any $\sigma \in \mathbb{N}_0^3$ with $|\sigma| \ge 1$ and any $t > 0$ there exists $C$, depending on $\sigma$ but independent of $t$, such that
\begin{equation}
\label{dcutoff_factors1}
|\partial^{\sigma} \zeta_{t}(x)|,\, |\partial^{\sigma} \theta_{t}(x)| \le C t^{-|\sigma|} \mathds{1}_{\{(4N)^{-1}t < |x| < (2N)^{-1}t\}}(x)
\end{equation}
for all $x \in \mathbb{R}^3$.

Without loss we consider the case of $\zeta_{t}$, the case of $\theta_{t}$ being similar. Recall $\xi = \xi(s)$ was defined in (\ref{eq:chi_def}) and we denote by $\xi^{(m)}$ the $m$-th (univariate) derivative of $\xi$. Since $|\sigma| \ge 1$ the chain rule shows that $\partial^{\sigma} \zeta_{t}(x)$ can be written as a sum of terms of the form
\begin{equation}
\label{dtheta}
(4Nt^{-1})^m \, \xi^{(m)}\big(4N|x|t^{-1}\big)\, \partial^{\sigma_1} |x| \, \dots \,\partial^{\sigma_m} |x|
\end{equation}
where $1 \le m \le |\sigma|$, and $\sigma_1, \dots, \sigma_m \in \mathbb{N}_0^3$ are non-zero multiindices obeying
\begin{equation*}
\sigma_1 + \dots + \sigma_m = \sigma.
\end{equation*}
Since $m \ge 1$, we have that if $\xi^{(m)}(s) \ne 0$ then $s \in (1,2)$. Therefore, for any term (\ref{dtheta}) to be non-zero we require that
\begin{equation}
\label{l_bound}
(4N)^{-1}t < |x| <(2N)^{-1}t.
\end{equation}


By the remark preceeding the current lemma, there exists $C$, dependent on $\sigma_1, \dots, \sigma_m$, such that
\begin{align*}

\partial^{\sigma_1} |x| \, \dots \,\partial^{\sigma_m} |x| \le  C|x|^{m-|\sigma|} \le C(4N)^{|\sigma|-m} t^{m-|\sigma|},
\end{align*}
using (\ref{l_bound}). Therefore, the terms (\ref{dtheta}) can readily be bounded to give the desired result.

\label{lem:dpphi_prime}
Let $0<2\delta \le \epsilon$ and $\Phi = \Phi_{\delta,\epsilon}$ be a cutoff of the form (\ref{eq:pphi_def}). Let $Q=Q(\Phi)$. Then for any multiindex $\boldsymbol\alpha \in \mathbb{N}_0^{3N+3}$ there exists $C$, dependent on $\boldsymbol\alpha$ but independent of $\delta$ and $\epsilon$, such that for any partial products $\Phi'$ of $\Phi$ we have
\begin{align}
\label{partial_a}
|\partial^{\boldsymbol\alpha}\Phi'(x,y,\bold{\hat{x}})| \le
\begin{cases}
C \epsilon^{-|\boldsymbol\alpha|} &\text{ if } \Phi' = \Phi(\,\cdot\,;Q,Q^c)\\
C \big(\epsilon^{-|\boldsymbol\alpha|} + \delta^{-|\boldsymbol\alpha|} M_{\delta}(x,y,\bold{\hat{x}})\big) &\text{ otherwise.}\\
\end{cases}
\end{align}

Lemma \ref{dcutoff_factors} gives bounds for the partial derivatives of the functions $\zeta_{\delta}, \theta_{\delta}, \zeta_{\epsilon}, \theta_{\epsilon}$. Considering $\theta_{\delta}\zeta_{\epsilon}$, we apply the Leibniz rule with $\sigma \in \mathbb{N}_0^3$, $|\sigma| \ge 1$, to obtain, for $z \in \mathbb{R}^3$
\begin{align}
\label{dcutoff_factor_final3}
\partial^{\sigma} (\theta_{\delta}\zeta_{\epsilon})(z) &= \sum_{\mu \le \sigma} {\sigma \choose \mu} \partial^{\mu} \theta_{\delta}(z) \partial^{\sigma-\mu} \zeta_{\epsilon}(z)
= \partial^{\sigma} \theta_{\delta}(z) + \partial^{\sigma} \zeta_{\epsilon}(z),
\end{align}
since, for each $\mu \le \sigma$ with $\mu \ne 0$ and $\mu \ne \sigma$ we have
\begin{equation*}
\partial^{\mu} \theta_{\delta}(z)\, \partial^{\sigma-\mu}\zeta_{\epsilon}(z) \equiv 0
\end{equation*}
by Lemma \ref{dcutoff_factors} and that $2\delta \le \epsilon$.
\paragraph{}
Now, to evaluate $\partial^{\boldsymbol\alpha}\Phi'$ for a general $\Phi'$ we apply the Leibniz rule to the product (\ref{beprime}) using (\ref{dcutoff_factor_final3}) where appropriate. Differentiated cutoff factors $\zeta_\delta, \theta_\delta, \zeta_\epsilon, \theta_\epsilon$ are bounded by (\ref{dcutoff_factors1}). The indicator function in this bound is not required in the case of $\zeta_\epsilon$ or $\theta_\epsilon$, whereas in the case of $\zeta_\delta$ or $\theta_\delta$ the indicator function is bounded above by $M_t$. Any remaining undifferentiated cutoff factors are bounded above by 1. If $\Phi' = \Phi(\,\cdot\,;Q,Q^c)$, all cutoff factors are of the form $\theta_{\epsilon}$ by Lemma \ref{lem:pphi_qqc} and therefore we need only use the bounds in (\ref{dcutoff_factors1}) with $t=\epsilon$.

\label{lem:dphi}
Let $0<2\delta \le \epsilon$ and $\Phi=\Phi_{\delta,\epsilon}$ be a cutoff of the form (\ref{eq:pphi_def}). Let $Q=Q(\Phi)$. For any multiindices $\alpha \in \mathbb{N}_0^3$ and $\boldsymbol\sigma \in \mathbb{N}_0^{3N+3}$ there exists $C$, independent of $\epsilon$ and $\delta$, such that
\begin{equation*}
|\partial^{\boldsymbol\sigma} D^{\alpha}_{x,y,Q} \Phi(x,y, \bold{\hat{x}})| \le C \epsilon^{-|\alpha|}\big( \epsilon^{-|\boldsymbol\sigma|} + \delta^{-|\boldsymbol\sigma|} M_{\delta}(x,y,\bold{\hat{x}})\big)
\end{equation*}
for all $x,y,\bold{\hat{x}}$.

First, set $\Phi' = \Phi(\,\cdot\,;Q) \, \Phi(\,\cdot\,;Q^c)$ and $\Phi'' = \Phi(\,\cdot\,;Q,Q^c)$. We then have
\begin{equation*}

D^{\alpha}_{x,y,Q} \Phi = \Phi'\, D^{\alpha}_{x,y,Q} \Phi''
\end{equation*}
which follows from Lemmas \ref{phi_factors_lem} and \ref{dqpq_lem}, and that $\Phi(\,\cdot\,;Q^c)$ is not dependent on variables involved in the $D^{\alpha}_{x,y,Q}$-derivative. By the definition (\ref{eq:dxybc}), the derivative $D^{\alpha}_{x,y,Q} \Phi''$ can be written as a sum of partial derivatives of the form $\partial^{\boldsymbol\alpha} \Phi''$ where $\boldsymbol\alpha \in \mathbb{N}_0^{3N+3}$ obeys $|\boldsymbol\alpha| = |\alpha|$. Now, by the Leibniz rule and Lemma \ref{lem:dpphi_prime} there exists some constants $C$ and $C'$, independent of $\delta$ and $\epsilon$, such that
\begin{align*}
|\partial^{\boldsymbol\sigma} (\Phi' \, \partial^{\boldsymbol\alpha} \Phi'' )| &\le \sum_{\boldsymbol{\tau} \le \boldsymbol\sigma} {\boldsymbol\sigma \choose \boldsymbol{\tau}} |\partial^{\boldsymbol{\tau}}\Phi'| \, |\partial^{\boldsymbol\sigma-\boldsymbol{\tau}+\boldsymbol\alpha} \Phi''|\\
&\le C\sum_{\boldsymbol{\tau} \le \boldsymbol\sigma} (\epsilon^{-|\boldsymbol{\tau}|} + \delta^{-|\boldsymbol{\tau}|}M_{\delta}) \epsilon^{-|\boldsymbol\sigma|+|\boldsymbol{\tau}|-|\boldsymbol\alpha|}\\
&\le C'\epsilon^{-|\alpha|}(\epsilon^{-|\boldsymbol\sigma|} + \delta^{-|\boldsymbol\sigma|}M_{\delta}),
\end{align*}
completing the proof.

\label{prop:ff}
Given $R >0$, there exists $C$ such that
\begin{equation}
\label{eq:ff_int}
\int_{\mathbb{R}^{3N-3}} f_{\infty}(x,\bold{\hat{x}}; R) f_{\infty}(y,\bold{\hat{x}};R)\, d\bold{\hat{x}} \le C \left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(x, 2R))} \left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(y, 2R))} 
\end{equation}
for all $x,y \in \mathbb{R}^3$. In addition, given $G \in L^1(\mathbb{R}^3)$ there exists $C$, independent of $G$, such that
\begin{multline}
\label{eq:gff_int}
\int_{\mathbb{R}^{3N-3}} \big(|G(x_j - x_k)| + |G(z- x_k)| + |G(x_j)|\big) f_{\infty}(x,\bold{\hat{x}}; R) f_{\infty}(y,\bold{\hat{x}};R)\, d\bold{\hat{x}} \\\le C\left\lVertG\right\rVert_{L^1(\mathbb{R}^3)} \left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(x, 2R))} \left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(y, 2R))} 
\end{multline}
for all $x,y, z \in \mathbb{R}^3$, and $j, k =2, \dots, N$, $j \ne k$. In particular, for any $t>0$ there exists $C$, independent of $t$, such that
\begin{equation}
\label{eq:mt_int}
\int_{\mathbb{R}^{3N-3}} M_{t}(x,y,\bold{\hat{x}}) f_{\infty}(x,\bold{\hat{x}}; R) f_{\infty}(y,\bold{\hat{x}};R)\, d\bold{\hat{x}} \le C t^{3} \left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(x, 2R))} \left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(y, 2R))} 
\end{equation}
for all $x,y \in \mathbb{R}^3$.

\label{lem:lam_b}
Let $\Phi = \Phi_{\delta,\epsilon}$ be a cutoff of the form (\ref{eq:pphi_def}), and let $j,k,r,s$ be as in (\ref{eq:lam_b3}) and (\ref{eq:lam_b4}). Then for any $b = b_1+b_2+b_3$, $b\ne 3$, $b_1,b_2,b_3 \ge 0$ there exists $C$, independent of $x,y$ and $\delta,\epsilon$, such that
\begin{multline}
\label{eq:lam_b5}
\int_{\textnormal{supp}\,\Phi(x,y,\,\cdot\,)} |x-x_j|^{-b_1}|y-x_k|^{-b_2}|x_r-x_s|^{-b_3} f_{\infty}(x,\bold{\hat{x}}) f_{\infty}(y,\bold{\hat{x}}) \,d\bold{\hat{x}} \\\le
C(1+\delta^{\min\{0, 3-b\}}) \left\lVert\rho\right\rVert^{1/2}_{L^1(B(x,1))}\left\lVert\rho\right\rVert^{1/2}_{L^1(B(y,1))}.
\end{multline}

By Young's inequality,
\begin{align*}
|x-x_j|^{-b_1}|y-x_k|^{-b_2}|x_r-x_s|^{-b_3} \le \frac{1}{b}\big(b_1|x-x_j|^{-b} + b_2|y-x_k|^{-b} + b_3|x_r-x_s|^{-b} \big).
\end{align*}
It therefore suffices to prove (\ref{eq:lam_b5}) where only one of $b_1, b_2$ and $b_3$ is non-zero. We consider the case where this is $b_1$, the other cases are similar. We split the integral into one where $|x-x_j| \ge 1$ and one where $|x-x_j| < 1$. In the former case, we can bound using (\ref{eq:ff_int}) of Proposition \ref{prop:ff}, whereas in the latter we use (\ref{eq:gff_int}) of the same proposition with $G(x-x_j) = \mathds{1}_{\{(4N)^{-1}\delta < |x-x_j| < 1\}}(x-x_j)|x-x_j|^{-b}$. The lower bound can be included in the indicator function due to (\ref{eq:lam_b3}) of Lemma \ref{lem:support}.

\label{lem:glm}
Let $\Phi = \Phi_{\delta,\epsilon}$ be a cutoff of the form (\ref{eq:pphi_def}) with $P^* \cap S^* = \emptyset$. For all $l,m \in \mathbb{N}_0^3$, $|l|,|m| \le 1$, and all $\mu_1, \mu_2, \mu_3 \in \mathbb{N}_0^3$ which obey either
\begin{enumerate}[label=(\roman*)]
\item $|\mu_2|+|\mu_3| \ne 3$ with $\mu_1$ arbitrary, or

\item $|\mu_2|+|\mu_3| = 3$ and $\mu_1 = 0$,
\end{enumerate}
there exists a constant $C$ such that for all $0<2\delta \le \epsilon \le 1$ we have
\begin{multline}
\label{eq:dglm_int2}
|\partial_{x+y}^{\mu_1}\partial_x^{\mu_2}\partial_y^{\mu_3} \gamma_{l,m}(x,y; \Phi_{\delta,\epsilon})| \\\le C \epsilon^{-|\mu_1|-|\mu_2|-|\mu_3|}\delta^{\min\{0,\,3- |\mu_2|-|\mu_3|\}}
\left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(x, 1))} \left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(y, 1))}
\end{multline}
for all $|x|, |y| \ge \epsilon$ and $|x-y| \le 2\delta$.

\label{prop:glm}
Take any $l,m \in \mathbb{N}_0^3$, $|l|,|m| \le 1$, and any $\mu_1, \mu_2, \mu_3$ as in Lemma \ref{lem:glm}. Then there exists $C$ such that
\begin{equation}
\label{eq:prop_glm}
|\partial_{x+y}^{\mu_1}\partial_x^{\mu_2}\partial_y^{\mu_3}\gamma_{l,m}(x,y)| \le Cm(x,y)^{-|\mu_1|-|\mu_2|-|\mu_3|} |x-y|^{\min\{0,3-|\mu_2|-|\mu_3|\}}
\left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(x, 1))} \left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(y, 1))}
\end{equation}
for all $x,y \in \mathbb{R}^3$ obeying $0<|x-y| \le m(x,y)/2$.

Firstly, by Lemma \ref{pou} there exists a finite collection of cutoffs, $\Phi^{(j)}$, $j=1,\dots,J$, for some $J$, such that
\begin{equation}
\label{eq:g_pou}
\gamma_{l,m} = \sum_{j=1}^J \gamma_{l,m}\big(\,\cdot\,;\Phi_{\delta,\epsilon}^{(j)}\big)
\end{equation}
holds everywhere for all choices of $0< 2\delta \le \epsilon$.

Fix any $x,y$ such that $0<|x-y| \le m(x,y)/2$. Then set $\delta = |x-y|/2$ and $\epsilon = m(x,y)/2$. Index by $j_k$, where $k=1,\dots, K$ for some $K \le J$, the $j$'s such that $P(\Phi^{(j)})^* \cap S(\Phi^{(j)})^* = \emptyset$. The $j_k$'s do not depend on the choice of $\delta$ and $\epsilon$. By Lemma \ref{particle_ineqs},
\begin{equation}
\gamma_{l,m}(x',y') = \sum_{k=1}^{K} \gamma_{l,m}\big(x',y';\Phi_{\delta,\epsilon}^{(j_k)}\big)
\end{equation}
holds for all $|x'-y'| \ge |x-y|/2$. Then by Lemma \ref{lem:glm}, for each $k=1, \dots, K$, we have
\begin{align*}
&|\partial_{x'+y'}^{\mu_1}\partial_{x'}^{\mu_2}\partial_{y'}^{\mu_3}\gamma_{l,m}(x',y')| \le \sum_{k=1}^K\big|\partial_{x'+y'}^{\mu_1}\partial_{x'}^{\mu_2}\partial_{y'}^{\mu_3}\gamma_{l,m}\big(x',y';\Phi_{\delta,\epsilon}^{(j_k)}\big)\big|\\ 
&\qquad\le Cm(x,y)^{-|\mu_1|-|\mu_2|-|\mu_3|}|x-y|^{\min\{0,3-|\mu_2|-|\mu_3|\}}\left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(x', 1))} \left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(y', 1))}
\end{align*}

for all $x', y'$ such that $|x-y|/2 < |x'-y'| \le |x-y|$ and $|x'|,|y'| \ge m(x,y)/2$. In particular, it holds for $x'=x$ and $y'=y$. The constant $C$ does not depend on the choice of $\delta$ and $\epsilon$, therefore the bound holds for all required $x$ and $y$.

If $|\alpha|,|\beta| \ge 1$ then take any $l \le \alpha$ and $m \le \beta$ with $|l|=|m|=1$. We can then write
\begin{align*}
\partial_x^{\alpha} \partial_y^{\beta}\gamma = \partial_x^{\alpha-l} \partial_y^{\beta-m}\gamma_{l,m}.
\end{align*}
It is then straightforward to obtain the required bound by Proposition \ref{prop:glm} with $\mu_1 = 0$, $\mu_2 = \alpha - l$ and $\mu_3 = \beta - m$.

We now consider the case where either $\alpha$ or $\beta$ is zero. Without loss, assume $\beta = 0$. Let $l \le \alpha$ and $m \le \alpha-l$ obey $|l|=|m|=1$. We then have by (\ref{eq:2dd}),





\begin{align*}
\partial^{\alpha}_x\gamma &= \partial^{l+m}_{x+y}\partial_x^{\alpha-l-m}\gamma - \partial_x^{\alpha-l-m}\partial_y^{l+m}\gamma - \partial_x^{\alpha-m}\partial_y^m\gamma - \partial_x^{\alpha-l}\partial_y^l\gamma

\end{align*}
It suffices to bound each term separately. The final three terms have at least one derivative on each $x$ and $y$, hence we be treated as before. Next, the first term can be rewritten as $\partial^{l+m}_{x+y}\partial_x^{\alpha-l-m-r}\gamma_{r,0}$ for some $r \le \alpha-l-m$ with $|r|=1$. Use of Proposition \ref{prop:glm} with $\mu_1 = l+m$, $\mu_2 = \alpha-l-m-r$ and $\mu_3 = 0$ then gives the required bound.

\label{lem:lam_b2}
For any $x,y \in \mathbb{R}^3$ with $|x|, |y| \ge \epsilon$,

\begin{enumerate}[label=(\roman*)]
\item there exists $C$, independent of $\delta,\epsilon$ and $x,y,\bold{\hat{x}}$, such that when $\Phi(x,y,\hat{\mathbf x}) \ne 0$,
\begin{align}
\label{eq:pi_bnd}
\pi(x, y, \bold{\hat{x}}) &\ge C \epsilon,\\
\label{eq:lam_bnd}
\lambda(x, y, \bold{\hat{x}}) &\ge C \delta,
\end{align}

\item for any $b \ge 0$ be such that $b \ne 3$, there exists $C$, independent of $\delta,\epsilon$ and $x,y$, such that                                                                      
\begin{multline}
\label{eq:lam_bnd2}
\int_{\textnormal{supp}\,\Phi(x,y,\,\cdot\,)} \lambda(x, y, \bold{\hat{x}})^{-b} f_{\infty}(x,\bold{\hat{x}}) f_{\infty}(y,\bold{\hat{x}}) \,d\bold{\hat{x}} \\\le C \big(\epsilon^{-b} + \delta^{\min\{0, 3-b \}}\big) \left\lVert\rho\right\rVert^{1/2}_{L^1(B(x,1))}\left\lVert\rho\right\rVert^{1/2}_{L^1(B(y,1))}.
\end{multline}
\end{enumerate}

We can prove (i) using the expressions (\ref{eq:pi_alt}) and (\ref{eq:lam_alt}). The bound follows from Lemma \ref{lem:support} along with (\ref{eq:lam_b2}) of Lemma \ref{particle_ineqs}, since $P,S \subset Q$. For (ii) we use (\ref{eq:lam_alt}) to write
\begin{align*}
\lambda(x,y,\hat{\mathbf x})^{-b} \le C\big(\epsilon^{-b} + \sum_{k \in P^c}|x-x_k|^{-b} + \sum_{k \in S^c}|y-x_k|^{-b} + \sum_{\substack{j \in P^*,\, k \in P^c\, \text{or}\\ j \in S^*,\, k \in S^c}} |x_j - x_k|^{-b}\big)
\end{align*}
for some $C$ depending on $b$. The required inequality then follows from (\ref{eq:ff_int}) of Proposition \ref{prop:ff} for the first term above and from Lemma \ref{lem:lam_b} for the remaining terms.

\label{cor:lam_b}
For any $x,y \in \mathbb{R}^3$ with $|x|, |y| \ge \epsilon$,
\begin{multline}
\label{eq:lam_int2}
\int_{\mathbb{R}^{3N-3}} \lambda(x, y, \bold{\hat{x}})^{-2} f_{\infty}(x,\bold{\hat{x}}) f_{\infty}(y,\bold{\hat{x}}) |\nabla \Phi(x,y,\bold{\hat{x}})| \,d\bold{\hat{x}} \\\le C \epsilon^{-3} \left\lVert\rho\right\rVert^{1/2}_{L^1(B(x,1))}\left\lVert\rho\right\rVert^{1/2}_{L^1(B(y,1))}
\end{multline}
for some $C$, independent of $\delta, \epsilon$ and $x,y$.

Using Lemma \ref{lem:dphi} and (\ref{eq:lam_bnd}), the integral can be bounded by some constant multiplying
\begin{align*}
\int_{\textnormal{supp}\,\Phi(x,y,\,\cdot\,)} \big(\epsilon^{-1}\lambda(x, y, \bold{\hat{x}})^{-2} + \delta^{-3}M_{\delta}(x,y,\bold{\hat{x}}) \big) f_{\infty}(x,\bold{\hat{x}}) f_{\infty}(y,\bold{\hat{x}}) \,d\bold{\hat{x}}.
\end{align*}
Expanding, the first term is bounded by (\ref{eq:lam_bnd2}) and second is bounded using (\ref{eq:mt_int}) of Proposition \ref{prop:ff}.

\label{lem:dglm}
Let $\mu_1,\mu_2,\mu_3 \in \mathbb{N}_0^3$ be arbitrary and $l,m \in \mathbb{N}_0^3$ be such that $|l|,|m| \le 1$.


The derivative $\partial^{\mu_1}_{x+y}\partial^{\mu_2}_x \partial^{\mu_3}_y \gamma_{l,m}(x,y;\Phi)$ is equal to a linear combination of integrals of the form
\begin{multline}
\label{eq:dglm_int}
\int_{\mathbb{R}^{3N-3}} \big( D_Q^{\alpha_1} D_{\{P, S^*\}}^{(\alpha_2, \alpha_3)} \partial_{x}^{l} \psi(x,\bold{\hat{x}})\big) \big( D_Q^{\beta_1} D_{\{P^*, S\}}^{(\beta_2, \beta_3)} \partial_{y}^{m} \psi(y,\bold{\hat{x}})\big) \big(D_{x,y,Q}^{\sigma_1} D^{\sigma_2}_{x,P} D_{y,S}^{\sigma_3}\Phi(x,y,\bold{\hat{x}})\big)\, d\bold{\hat{x}}\\
\text{where } |\alpha_i| + |\beta_i| + |\sigma_i| = |\mu_i|,\, i=1,2,3
\end{multline}
for all $|x|, |y| \ge \epsilon$. In particular, the derivative exists across the diagonal $x=y$ for $|x|, |y| \ge \epsilon$.

For each choice of $x$ and $y$ we define a $x$- and $y$-dependent change of variables for the integral $\gamma_{l,m}(x,y;\Phi)$. To start, we define two vectors $\bold{\hat{a}} = (a_2, \dots, a_N), \bold{\hat{b}} = (b_2, \dots, b_N) \in \mathbb{R}^{3N-3}$ by

\begin{align}
a_k &=
\begin{cases}
x \quad & \text{ if } k \in P^*\\
y \quad & \text{ if } k \in S^*\\
0 \quad & \text{ if } k \in P^c \cap S^c,
\end{cases}
&
b_{k} &=
\begin{cases}
(x+y)/2 \quad & \text{ if } k \in Q^* \\
0 \quad & \text{ if } k \in Q^{c}.
\end{cases}
\end{align}
By a translational change of variables using $\bold{\hat{a}}$ we can write
\begin{equation}
\label{glm_phi}
\gamma_{l,m}(x,y; \Phi) = \int_{\mathbb{R}^{3N-3}} \partial_{x}^l \psi(x, \bold{\hat{x}} + \bold{\hat{a}}) \overline{\partial_y^m \psi(y, \bold{\hat{x}}+\bold{\hat{a}})} \Phi(x,y, \bold{\hat{x}}+\bold{\hat{a}})  \,d\bold{\hat{x}}.
\end{equation}





We will then apply differentiation under the integral. Beforehand, we show how such derivatives will act on each function within the integrand. As an illustration, we take a function $f$ defined on $\mathbb{R}^{3N}$ and any $\eta \in \mathbb{N}_0^3$ to see by the chain rule that
\begin{equation*}
  \begin{split}
\partial^{\eta}_{x+y}[f(x, \bold{\hat{x}}+\bold{\hat{b}})] &= D^{\eta}_Q f(x, \bold{\hat{x}}+\bold{\hat{b}}),\\
\partial^{\eta}_{x+y}[f(y, \bold{\hat{x}}+\bold{\hat{b}})] &= D^{\eta}_Q f(y, \bold{\hat{x}}+\bold{\hat{b}}),\\
\partial^{\eta}_x[f(x, \bold{\hat{x}}+\bold{\hat{a}})] &= D^{\eta}_P f(x, \bold{\hat{x}}+\bold{\hat{a}}),
  \end{split}
\qquad
  \begin{split}
\partial^{\eta}_x[f(y, \bold{\hat{x}}+\bold{\hat{a}})] &= D^{\eta}_{P^*} f(y, \bold{\hat{x}}+\bold{\hat{a}}),\\
\partial^{\eta}_y[f(x, \bold{\hat{x}}+\bold{\hat{a}})] &= D^{\eta}_{S^*} f(x, \bold{\hat{x}}+\bold{\hat{a}}),\\
\partial^{\eta}_y[f(y, \bold{\hat{x}}+\bold{\hat{a}})] &= D^{\eta}_S f(y, \bold{\hat{x}}+\bold{\hat{a}}).
  \end{split}
\end{equation*}

Analogous expressions arise when the cutoff $\Phi(x,y,\bold{\hat{x}})$ is differentiated which involve cluster derivatives of the form (\ref{eq:dxbc}), (\ref{eq:dxybc}).

We now differentiate (\ref{glm_phi}) in $x$ and $y$, and use the product rule to get that the function $\partial^{\mu_2}_x\partial^{\mu_3}_y \gamma_{l,m}(x,y; \Phi)$ is a linear combination of terms of the form




\begin{align*}
&I_{(\alpha_2,\alpha_3,\beta_2,\beta_3,\sigma_2,\sigma_3)}\\ 
&= \int_{\mathbb{R}^{3N-3}} \big( D_{\{P, S^*\}}^{(\alpha_2, \alpha_3)} \partial_{x}^{l} \psi(x,\bold{\hat{x}}+\bold{\hat{a}})\big) \big( D_{\{P^*, S\}}^{(\beta_2, \beta_3)} \partial_{y}^{m} \psi(y,\bold{\hat{x}}+\bold{\hat{a}})\big) D^{\sigma_2}_{x,P} D_{y,S}^{\sigma_3}\Phi(x,y,\bold{\hat{x}}+\bold{\hat{a}})\big)\, d\bold{\hat{x}},
\end{align*}
for some $\alpha_2+\beta_2+\sigma_2 = \mu_2$ and $\alpha_3+\beta_3+\sigma_3 = \mu_3$.

We will now apply a $(x+y)$-derivative to an integral of this form. However, first we apply a change of variables to replace $\bold{\hat{a}}$ with $\bold{\hat{b}}$ as the translation of the integration variable $\bold{\hat{x}}$. Then, in the same way as before, we obtain that $\partial^{\mu_1}_{x+y}I_{(\alpha_2,\alpha_3,\beta_2,\beta_3,\sigma_2,\sigma_3)}$ is a linear combination of terms of the form
\begin{multline*}
\int_{\mathbb{R}^{3N-3}} \big( D^{\alpha_1}_Q D_{\{P, S^*\}}^{(\alpha_2, \alpha_3)} \partial_{x}^{l} \psi(x,\bold{\hat{x}}+\bold{\hat{b}})\big) \big(  D^{\beta_1}_Q D_{\{P^*, S\}}^{(\beta_2, \beta_3)} \partial_{y}^{m} \psi(y,\bold{\hat{x}}+\bold{\hat{b}})\big)\,\cdot\\ 
 D^{\sigma_1}_{x,y,Q} D^{\sigma_2}_{x,P} D_{y,S}^{\sigma_3}\Phi(x,y,\bold{\hat{x}}+\bold{\hat{b}})\big)\, d\bold{\hat{x}}.
\end{multline*}
for some $\alpha_1+\beta_1+\sigma_1 = \mu_1$. Finally, another translational change of variables removes $\bold{\hat{b}}$ to give the expression (\ref{eq:dglm_int}).

Consider $\mu_1,\mu_2,\mu_3$ satisfying either (i) or (ii). By Lemma \ref{lem:dglm} it suffices to prove the required bound for integrals of the form (\ref{eq:dglm_int}). Define $a = |\alpha_1|+|\beta_1|+|\sigma_1|$, $b = |\alpha_2|+|\alpha_3|+|\beta_2|+|\beta_3|$ and $c = |\sigma_2|+|\sigma_3|$. Notice that $a = |\mu_1|$ and $b+c = |\mu_2|+|\mu_3|$. Then, using (\ref{eq:bc_1})-(\ref{eq:ddpsi_2}) and (\ref{eq:pi_bnd}) it is possible to bound (\ref{eq:dglm_int}) in absolute value by some constant multiplying

\begin{align*}
&\epsilon^{-a-c}\int_{\text{supp}\, \Phi(x,y,\cdot)} \lambda(x,y,\bold{\hat{x}})^{-b} f_{\infty}(x,\bold{\hat{x}}) f_{\infty}(y,\bold{\hat{x}}) \, d\bold{\hat{x}}\\
&\qquad +\epsilon^{-a}\delta^{-c} \int_{\text{supp}\, \Phi(x,y,\cdot)} M_{\delta}(x,y,\bold{\hat{x}}) \lambda(x,y,\bold{\hat{x}})^{-b} f_{\infty}(x,\bold{\hat{x}}) f_{\infty}(y,\bold{\hat{x}}) \, d\bold{\hat{x}} =: I_1 + I_2.
\end{align*}

For $I_2$ we use (\ref{eq:lam_bnd}) to bound this by some constant multiplying

\begin{align*}
\epsilon^{-a}\delta^{-c-b} \int_{\mathbb{R}^{3N-3}} M_{\delta}(x,y,\bold{\hat{x}}) f_{\infty}(x,\bold{\hat{x}}) f_{\infty}(y,\bold{\hat{x}}) \, d\bold{\hat{x}}\le C\epsilon^{-a} \delta^{3-b-c} \left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(x, 1))} \left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(y, 1))}
\end{align*}
for some $C$, where we used (\ref{eq:mt_int}). This gives (\ref{eq:dglm_int2}) for $I_2$.


For $I_1$, we first consider when $b \ne 3$. By (\ref{eq:lam_bnd2}), this is bounded by some constant multiplying
\begin{align*}
(\epsilon^{-a-c-b} + \epsilon^{-a-c}\delta^{\min\{0,3-b\}})\left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(x, 1))} \left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(y, 1))}
\end{align*}

which is then bounded by (\ref{eq:dglm_int2}).


Now we consider $I_1$ for $b = 3$. If we are in case (i) then we must have $c \ge 1$ since $b + c = |\mu_1|+|\mu_2| \ne 3$. Here, we use (\ref{eq:lam_bnd}) followed by (\ref{eq:lam_bnd2}) to bound $I_1$ by some constant multiplying
\begin{multline*}
\epsilon^{-a-c} \delta^{-1}\int_{\text{supp}\, \Phi(x,y,\cdot)} \lambda(x,y,\bold{\hat{x}})^{-2} f_{\infty}(x,\bold{\hat{x}}) f_{\infty}(y,\bold{\hat{x}}) \, d\bold{\hat{x}} \\\le C\epsilon^{-a-c-2}\delta^{-1}\left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(x, 1))} \left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(y, 1))}
\end{multline*}

for some $C$, which is then bounded by (\ref{eq:dglm_int2}). Finally, if we are in case (ii) for $b=3$ then $I_1$ cannot be bounded appropriately. Instead, we use that the integral (\ref{eq:dglm_int}) that we are attempting to bound must have $\alpha_1 = \beta_1 = 0$ and $\sigma_i = 0$, $i=1,2,3$. This allows us to use Lemma \ref{lem:ab3}, which is stated and proven below, to bound (\ref{eq:dglm_int}) directly.

\label{lem:ab3}
For any $\boldsymbol\alpha = (\alpha_1,\alpha_2), \boldsymbol\beta=(\beta_1,\beta_2) \in \mathbb{N}_0^6$ with $|\boldsymbol\alpha| + |\boldsymbol\beta| = 3$, and any $l,m \in \mathbb{N}_0^3$ with $|l|,|m| \le 1$ there exists $C$, independent of $\delta,\epsilon$, such that
\begin{multline}
\label{eq:ab3}
\Big|\int_{\mathbb{R}^{3N-3}} \big(D_{\{P, S^*\}}^{\boldsymbol\alpha}\partial_x^l \psi(x,\bold{\hat{x}})\big) \big(D_{\{P^*, S\}}^{\boldsymbol\beta}\partial_y^m \psi(y,\bold{\hat{x}})\big) \Phi_{\delta,\epsilon}(x,y,\bold{\hat{x}})\, d\bold{\hat{x}}\Big| \\\le C\epsilon^{-3}\left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(x, 1))} \left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(y, 1))}
\end{multline}
for all $|x|, |y| \ge \epsilon$ with $|x-y| \le 2\delta$.

\label{lem:Fee}
For any $|l|=|m|=1$ and $|\boldsymbol\alpha|, |\boldsymbol\beta| \ge 1$ we have
\begin{align}
\label{eq:fee_1}
D_{\{P, S^* \}}^{\boldsymbol{\alpha}} \partial_x^l F^{(ee)}_{c}(x,\bold{\hat{x}}) =
\begin{cases}
\frac{(-1)^{|\alpha_1|+1}}{4}\sum_{j \in S^*}  \partial_{x_j}^{\alpha_1 + \alpha_2 + l} |x - x_j|\quad &\text{if } |\alpha_2| \ge 1\\
\frac{(-1)^{|\alpha_1|+1}}{4}\sum_{j \in P^c}  \partial_{x_j}^{\alpha_1 + l} |x - x_j| \quad &\text{if } \alpha_2 = 0,\\
\end{cases}
\end{align}
\begin{align}
\label{eq:fee_2}
D_{\{P^*, S\}}^{\boldsymbol\beta} \partial_y^m F^{(ee)}_{c}(y,\bold{\hat{x}}) = 
\begin{cases}
\frac{(-1)^{|\beta_2|+1}}{4}\sum_{j \in P^*}  \partial_{x_j}^{\beta_1 + \beta_2 + m} |y - x_j| \quad &\text{if } |\beta_1| \ge 1\\
\frac{(-1)^{|\beta_2|+1}}{4}\sum_{j \in S^c}  \partial_{x_j}^{\beta_2 + m} |y - x_j|\quad &\text{if } \beta_1 = 0.
\end{cases}
\end{align}

We first consider the more difficult case of $|l|=|m|=1$. By Theorem \ref{thm:ddpsi} with $b=1/2$ we can write
\begin{align}
\label{eq:gps_def1}
D_{\{P,S^*\}}^{\boldsymbol\alpha}\nabla \psi &= G_{\{P,S^*\}}^{\boldsymbol\alpha} + \psi\big( D_{\{P,S^*\}}^{\boldsymbol\alpha}\nabla F_c\big) \quad &&\text{for } |\boldsymbol\alpha| \ge 1,\\
\label{eq:gps_def2}
D_{\{P^*,S\}}^{\boldsymbol\beta}\nabla \psi &= G_{\{P^*,S\}}^{\boldsymbol\beta} + \psi\big( D_{\{P^*,S\}}^{\boldsymbol\beta}\nabla F_c\big)  \quad &&\text{for } |\boldsymbol\beta| \ge 1,
\end{align}
and in these cases we have the estimates
\begin{align}
\label{eq:gps_bnd1}
\big|G^{\boldsymbol\alpha}_{\{P,S^*\}}(x, \bold{\hat{x}})\big| &\le C \lambda(x, y, \bold{\hat{x}})^{1/2-|\boldsymbol\alpha|} f_{\infty}(x, \bold{\hat{x}}),\\
\label{eq:gps_bnd2}
\big|G^{\boldsymbol\beta}_{\{P^*,S\}}(y, \bold{\hat{x}})\big| &\le C \lambda(x, y, \bold{\hat{x}})^{1/2-|\boldsymbol\beta|} f_{\infty}(y, \bold{\hat{x}}).
\end{align}


With these preliminary estimates, we can prove the result in the case where $|\boldsymbol\alpha|,|\boldsymbol\beta| \ge 1$. By (\ref{eq:gps_def1}), (\ref{eq:gps_def2}) and $F_c = F^{(en)}_c + F^{(ee)}_c$ we bound the integral (\ref{eq:ab3}) by
\begin{align*}
&\int_{\mathbb{R}^{3N-3}} \big|G_{\{P, S^* \}}^{\boldsymbol\alpha}(x, \bold{\hat{x}})\big| \big|D_{\{P^*, S\}}^{\boldsymbol\beta}\nabla_y \psi(y,\bold{\hat{x}})\big| \Phi(x,y,\bold{\hat{x}})\, d\bold{\hat{x}}\\ 
&\qquad+ \int_{\mathbb{R}^{3N-3}} \big|D_{\{P, S^*\}}^{\boldsymbol\alpha}\nabla_x F_c(x,\bold{\hat{x}})\big| | \psi(x,\bold{\hat{x}})| \big|G_{\{P^*, S \}}^{\boldsymbol\beta}(y, \bold{\hat{x}})\big| \Phi(x,y,\bold{\hat{x}})\, d\bold{\hat{x}}\\ 
&\qquad+ \int_{\mathbb{R}^{3N-3}} \big|D_{\{P, S^*\}}^{\boldsymbol\alpha}\nabla_x F^{(en)}_c(x,\bold{\hat{x}})\big| |\psi(x,\bold{\hat{x}})| \big|D_{\{P^*, S\}}^{\boldsymbol\beta}\nabla_y F_c(y,\bold{\hat{x}})\big| |\psi(y,\bold{\hat{x}})| \Phi(x,y,\bold{\hat{x}})\, d\bold{\hat{x}}\\
&\qquad+ \int_{\mathbb{R}^{3N-3}} \big|D_{\{P, S^*\}}^{\boldsymbol\alpha}\nabla_x F^{(ee)}_c(x,\bold{\hat{x}})\big| |\psi(x,\bold{\hat{x}})|  \big|D_{\{P^*, S\}}^{\boldsymbol\beta}\nabla_y F^{(en)}_c(y,\bold{\hat{x}})\big| |\psi(y,\bold{\hat{x}})| \Phi(x,y,\bold{\hat{x}})\, d\bold{\hat{x}}\\
&\qquad+ \Big|\int_{\mathbb{R}^{3N-3}} \big(D_{\{P, S^*\}}^{\boldsymbol\alpha}\partial_x^l F^{(ee)}_c(x,\bold{\hat{x}})\big)  \big(D_{\{P^*, S\}}^{\boldsymbol\beta}\partial_y^m F^{(ee)}_c(y,\bold{\hat{x}})\big) \psi(x,\bold{\hat{x}}) \overline{\psi(y,\bold{\hat{x}})} \Phi(x,y,\bold{\hat{x}})\, d\bold{\hat{x}}\Big|.
\end{align*}

By Lemma \ref{lem:Fee} the final term above can be expanded by terms of the form (\ref{eq:ijk}), since $S^* \subset P^c$ and $P^* \subset S^c$. Lemma \ref{lem:ff_int} then gives the appropriate bound. We will now show that each of the remaining integrals above can be bounded by a constant multiplying an integral of the form
\begin{align}
\label{eq:eps_lam}
\epsilon^{-a} \int_{\mathbb{R}^{3N-3}} \lambda(x,y,\bold{\hat{x}})^{-b}  f_{\infty}(x,\bold{\hat{x}}) f_{\infty}(y,\bold{\hat{x}}) \Phi(x,y,\bold{\hat{x}}) \,d\bold{\hat{x}}.
\end{align}
for some $a,b \ge 0$, $b \le 5/2$ and $a + b \le 3$. This follows from using the estimates (\ref{eq:ddfc}), (\ref{eq:fen}), (\ref{eq:gps_bnd1}) and (\ref{eq:gps_bnd2}).                                                                                                                                              
We also use (\ref{eq:ddpsi_2}) to bound the cluster derivatives of $\psi(y,\bold{\hat{x}})$ in the first term. The required bound then follows by Lemma \ref{lem:lam_b2}.

Next we consider the case where $|\boldsymbol\alpha|=3$ and $\boldsymbol\beta = 0$. The other case where $|\boldsymbol\beta|=3$ and $\boldsymbol\alpha = 0$ is similar with obvious modifications. By (\ref{eq:gps_def1}) and $F_c = F^{(en)}_c + F^{(ee)}_c$ we bound the integral (\ref{eq:ab3}) by
\begin{align*}
&\int_{\mathbb{R}^{3N-3}} \big|G_{\{P, S^* \}}^{\boldsymbol\alpha}(x, \bold{\hat{x}})\big| |\nabla \psi(y,\bold{\hat{x}})| \Phi(x,y,\bold{\hat{x}})\, d\bold{\hat{x}}\\ 
&\qquad+ \int_{\mathbb{R}^{3N-3}} \big|D_{\{P, S^*\}}^{\boldsymbol\alpha}\partial_x^l F^{(en)}_c(x,\bold{\hat{x}})\big| |\psi(x,\bold{\hat{x}})| |\nabla \psi(y,\bold{\hat{x}})| \Phi(x,y,\bold{\hat{x}})\, d\bold{\hat{x}}\\
&\qquad+ \Big|\int_{\mathbb{R}^{3N-3}} \big(D_{\{P, S^*\}}^{\boldsymbol\alpha}\partial_x^l F^{(ee)}_c(x,\bold{\hat{x}})\big) \psi(x,\bold{\hat{x}}) \overline{\partial_y^m \psi(y,\bold{\hat{x}})} \Phi(x,y,\bold{\hat{x}})\, d\bold{\hat{x}}\Big| =: I_1+I_2+I_3.
\end{align*}
The integral $I_1$ is bounded using (\ref{eq:gps_bnd1}), from which we can then apply Lemma \ref{lem:lam_b2}. Bounding $I_2$ is a simple application of (\ref{eq:fen}) and Proposition \ref{prop:ff}. For $I_3$ we use the expression $\psi = e^F\phi$, where $\phi$ was introduced in (\ref{phi_def}). Since $F = F^{(ee)}_c + F_c^{(en)} - F_s$ we can write
\begin{align*}
\partial_y^m \psi(y,\bold{\hat{x}}) = e^{F(y,\bold{\hat{x}})} \partial_y^m\phi(y,\bold{\hat{x}}) + \psi(y,\bold{\hat{x}}) \partial_y^m F^{(ee)}_c(y,\bold{\hat{x}}) + \psi(y,\bold{\hat{x}}) \big(\partial_y^m F^{(en)}_c(y,\bold{\hat{x}}) - \partial_y^m F_s(y,\bold{\hat{x}})\big).
\end{align*}
We expand $I_3$ according to this expression. By Lemma \ref{lem:Fee}, the first term can be expanded in terms of the form (\ref{eq:ff_holder1}) and therefore can bounded by Lemma \ref{lem:ff_holder}. Also by Lemma \ref{lem:Fee}, the second term can be expanded in terms of the form (\ref{eq:ijk}) for $\beta = m$ and $|\alpha|=4$, and therefore can bounded by Lemma \ref{lem:ff_int}. It therefore suffices to bound
\begin{align*}
\int_{\mathbb{R}^{3N-3}}  \big(D_{\{P, S^*\}}^{\boldsymbol{\boldsymbol\alpha}} \partial_x^l F^{(ee)}_c(x,\bold{\hat{x}})\big) \big(\partial_y^m F^{(en)}_c(y,\mathbf x) - \partial_y^m F_s(y,\mathbf x)\big) \psi(x,\bold{\hat{x}}) \overline{\psi(y,\mathbf x)} \Phi(x,y,\bold{\hat{x}}) \,d\bold{\hat{x}}.
\end{align*}
We expand the derivative of $F_c^{(ee)}$ using Lemma \ref{lem:Fee}. A general term in this expansion will have the form
\begin{align*}
\int_{\mathbb{R}^{3N-3}}  \partial_{x_j}^{\alpha+l}|x-x_j| \big(\partial_y^m F^{(en)}_c(y,\mathbf x) - \partial_y^m F_s(y,\mathbf x)\big) \psi(x,\bold{\hat{x}}) \overline{\psi(y,\mathbf x)} \Phi(x,y,\bold{\hat{x}}) \,d\bold{\hat{x}}
\end{align*}
for some $j \in P^c$ and $|\alpha| = 3$. We write this integral as follows, using integration by parts to remove one derivative from $|x-x_j|$,
\begin{align*}
&-\int_{\mathbb{R}^{3N-3}}  \partial_{x_j}^{\alpha}|x-x_j| \big(\partial_y^m F^{(en)}_c(y,\mathbf x) - \partial_y^m F_s(y,\mathbf x)\big) \partial_{x_j}^l \big(\psi(x,\bold{\hat{x}}) \overline{\psi(y,\mathbf x)} \big) \Phi(x,y,\bold{\hat{x}}) \,d\bold{\hat{x}}\\
&\qquad- \int_{\mathbb{R}^{3N-3}}  \partial_{x_j}^{\alpha}|x-x_j| \big(\partial_y^m F^{(en)}_c(y,\mathbf x) - \partial_y^m F_s(y,\mathbf x)\big) \psi(x,\bold{\hat{x}}) \overline{\psi(y,\mathbf x)} \partial_{x_j}^l \Phi(x,y,\bold{\hat{x}}) \,d\bold{\hat{x}}\\
&\qquad +\int_{\mathbb{R}^{3N-3}} \partial_{x_j}^{\alpha}|x-x_j| \partial_{x_j}^l\partial_y^m F_s(y,\mathbf x) \psi(x,\bold{\hat{x}}) \overline{\psi(y,\mathbf x)} \Phi(x,y,\bold{\hat{x}}) \,d\bold{\hat{x}}
\end{align*}
since $\partial_{x_j}^l\partial_y^m F^{(en)}_c(y,\mathbf x) \equiv 0$. We now use (\ref{eq:modx_lam}), that $\nabla F^{(en)}_c \in L^{\infty}(\mathbb{R}^{3N})$ and that $\nabla^k F_s \in L^{\infty}(\mathbb{R}^{3N})$ for any integer $k \ge 1$, see (\ref{f2_linf}). Therefore, these terms can be bounded by some constant multiplying
\begin{align*}
\int_{\mathbb{R}^{3N-3}} \lambda(x,y,\bold{\hat{x}})^{-2}  f_{\infty}(x,\bold{\hat{x}}) f_{\infty}(y,\bold{\hat{x}}) \big(\Phi(x,y,\bold{\hat{x}}) + |\nabla\Phi(x,y,\hat{\mathbf x})|\big) \,d\bold{\hat{x}}
\end{align*}
which is bounded appropriately by Lemma \ref{lem:lam_b2} and Corollary \ref{cor:lam_b}.

Finally, it remains to consider the case where one or both of $l$, $m$ are zero. The strategy is analogous but simpler. We remark that we can use the following improved version of (\ref{eq:ddpsi_1}) and (\ref{eq:ddpsi_2}) in the case where $\eta = 0$ and $k=0$. For any $\boldsymbol{\nu} = (\nu_1, \nu_2) \in \mathbb{N}_0^6$ with $|\boldsymbol\nu| \ge 1$ there exists some $C$ such that
\begin{align*}
\big|D^{\boldsymbol\nu}_{\{P,S^*\}} \psi(x, \bold{\hat{x}})\big| &\le C \lambda(x, y, \bold{\hat{x}})^{1-|\boldsymbol\nu|} f_{\infty}(x, \bold{\hat{x}}),\\
\big|D^{\boldsymbol\nu}_{\{P^*,S\}}  \psi(y, \bold{\hat{x}})\big| &\le C\lambda(x, y, \bold{\hat{x}})^{1-|\boldsymbol\nu|} f_{\infty}(y, \bold{\hat{x}}).
\end{align*}
These inequalities follow immediately from (\ref{eq:ddpsi}) of Theorem \ref{thm:ddpsi}.

\label{lem:ff_int}
Let $|\alpha|,|\beta| \ge 1$ be such that $|\alpha| + |\beta| \le 5$. Then for any pair $2 \le j,k \le N$ such that $j \in P^c$ if $|\alpha| \ge 2$ and $k \in S^c$ if $|\beta| \ge 2$ we have for
\begin{align}
\label{eq:ijk}
I_{j,k} := \int_{\mathbb{R}^{3N-3}} \partial_{x_j}^{\alpha}|x-x_j| \partial_{x_k}^{\beta} |y-x_k| \psi(x,\bold{\hat{x}}) \overline{\psi(y,\bold{\hat{x}})}  \Phi(x,y,\bold{\hat{x}}) \,d\bold{\hat{x}},
\end{align}
that there exists $C$, independent of $\delta$ and $\epsilon$, such that
\begin{align*}
|I_{j,k}| \le C\epsilon^{2-|\alpha|-|\beta|}\left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(x, 1))} \left\lVert\rho\right\rVert^{1/2}_{L^{1}(B(y, 1))}
\end{align*}
for all $|x|,|y| \ge \epsilon$ and $|x-y| \le 2\delta$.

We suppose that $|\alpha| + |\beta| = 5$ otherwise the result follows immediately from (\ref{eq:modx_lam}) and Lemma \ref{lem:lam_b2}.


We first prove the case where $j \ne k$, where the integration by parts is particularly simple. Suppose without loss that $|\alpha| \ge |\beta|$. Then take any $l \le \alpha$ with $|l|=1$ and use integration by parts to obtain

\begin{align}
\label{eq:ijk2}
I_{j,k} &= -\int_{\mathbb{R}^{3N-3}} \partial_{x_j}^{\alpha-l}|x-x_j| \partial_{x_k}^{\beta} |y-x_k| \partial_{x_j}^{l} \big( \psi(x,\bold{\hat{x}}) \psi(y,\bold{\hat{x}})  \Phi(x,y,\bold{\hat{x}})\big) \,d\bold{\hat{x}}.
\end{align}
This can then be bounded in absolute value as required using (\ref{eq:modx_lam}) followed by either Lemma \ref{lem:lam_b2} or Corollary \ref{cor:lam_b}. This completes the proof where $j \ne k$.






For the remainder of the proof we consider the case where $j = k$. First, suppose $j \in P^c \cap S^c$.                                                                    
In the procedure that follows, we will use integration by parts to remove all derivatives from $|y-x_j|$ in $I_{j,j}$.                                                                                                                             


Since $|\beta| \ge 1$ we can find some multiindex $\beta_1 \le \beta$ with $|\beta_1| = 1$. Integration by parts then gives
\begin{align}
\nonumber
I_{j,j} = &-\int_{\mathbb{R}^{3N-3}} \partial_{x_j}^{\alpha+\beta_1} |x-x_j| \partial_{x_j}^{\beta-\beta_1} |y-x_j| \psi(x,\bold{\hat{x}}) \psi(y,\bold{\hat{x}}) \Phi(x,y,\bold{\hat{x}}) \,d\bold{\hat{x}}\\
\label{eq:ikk_ibp}
&-\int_{\mathbb{R}^{3N-3}} \partial_{x_j}^{\alpha} |x-x_j| \partial_{x_j}^{\beta - \beta_1} |y-x_j| \partial_{x_j}^{\beta_1} \big(\psi(x,\bold{\hat{x}}) \psi(y,\bold{\hat{x}}) \Phi(x,y,\bold{\hat{x}})\big) \,d\bold{\hat{x}}.
\end{align}
We leave untouched the second integral above. For the first, if $|\beta| - |\beta_1| \ge 1$ we can remove another first-order derivative from $|y-x_j|$ by the same procedure. That is, using integration by parts to give two new terms as in (\ref{eq:ikk_ibp}). We retain the term where the derivative falls on $\psi(x,\bold{\hat{x}}) \psi(y,\bold{\hat{x}}) \Phi(x,y,\bold{\hat{x}})$. Whereas on the term where the derivative falls on $|x-x_j|$ we repeat the procedure, so long as there remains at least one derivative on $|y-x_j|$. Through this process, we obtain a formula for $I_{j,j}$. To express this formula, we first set $T=|\beta|$ and write $\beta = \sum_{s=1}^{T}\beta_s$ for some collection $|\beta_s| = 1$ where $1 \le s \le T$. Furthermore, we define
\begin{align*}
\beta_{<i} =
\begin{cases}
0 &\text{ if } i=1\\
\beta_1 &\text{ if } i=2\\
\beta_1 + \dots + \beta_{i-1} &\text{ if } i \ge 3
\end{cases}
\qquad \beta_{>i} =
\begin{cases}
0 &\text{ if } i=T\\
\beta_{T} &\text{ if } i=T-1\\
\beta_{i+1} + \dots + \beta_{T} &\text{ if } i \le T-2.
\end{cases}
\end{align*}
Then,
\begin{align}
\label{eq:ikk_iter}
I_{j,j} = (-1)^{T}\int_{\mathbb{R}^{3N-3}} \partial_{x_j}^{\alpha+\beta} |x-x_j| |y-x_j| \psi(x,\bold{\hat{x}}) \psi(y,\bold{\hat{x}}) \Phi(x,y,\bold{\hat{x}}) \,d\bold{\hat{x}}
+ \sum_{i=1}^{T}  (-1)^i I^{(i)}_{j,j}
\end{align}
where
\begin{equation*}
I^{(i)}_{j,j} = \int_{\mathbb{R}^{3N-3}} \partial_{x_j}^{\alpha+\beta_{<i}} |x-x_j| \partial_{x_j}^{\beta_{>i}} |y-x_j|
\partial_{x_j}^{\beta_i} \big(\psi(x,\bold{\hat{x}}) \psi(y,\bold{\hat{x}}) \Phi(x,y,\bold{\hat{x}})\big) \,d\bold{\hat{x}}.
\end{equation*}
We can bound $|I^{(i)}_{j,j}|$ for $1 \le i \le T-1$ in the same way as (\ref{eq:ijk2}) since $j \in P^c \cap S^c$. It remains to bound $I^{(T)}_{j,j}$, along with the first integral in formula (\ref{eq:ikk_iter}).

We begin by expanding $|y - x_j| = |x - x_j| + \big(|y-x_j| - |x-x_j| \big)$ and noticing that
\begin{equation}
\label{eq:delta_triangle}
\big||y-x_j| - |x- x_j| \big| \le |x-y| \le 2\delta.
\end{equation}
It is then straightforward to show (for example see the comment preceeding Lemma \ref{dcutoff_factors}) that for some $C,C'$,
\begin{align}
\label{eq:itkk}
\big|I^{(T)}_{j,j}\big| &\le C\int_{\mathbb{R}^{3N-3}} |x-x_j|^{-3} \big(2\delta + |x-x_j| \big)
\big|\partial_{x_j}^{\beta_T} \big(\psi(x,\bold{\hat{x}}) \psi(y,\bold{\hat{x}}) \Phi(x,y,\bold{\hat{x}})\big)\big| \,d\bold{\hat{x}}\\
\nonumber
&\le C'\int_{\mathbb{R}^{3N-3}} \lambda(x,y,\bold{\hat{x}})^{-2}  f_{\infty}(x,\bold{\hat{x}}) f_{\infty}(y,\bold{\hat{x}}) \big(\Phi(x,y,\bold{\hat{x}}) + |\nabla\Phi(x,y,\hat{\mathbf x})|\big) \,d\bold{\hat{x}}
\end{align}
where in the second step we used formula (\ref{eq:lam_alt}), since $j \in P^c$, along with (\ref{eq:lam_bnd}). This is then bounded as required by Lemma \ref{lem:lam_b2} and Corollary \ref{cor:lam_b}.

We now bound the first integral in (\ref{eq:ikk_iter}). Once again we use $|y - x_j| = |x - x_j| + \big(|y-x_j| - |x-x_j| \big)$, (\ref{eq:delta_triangle}) and (\ref{eq:lam_alt}) to show it suffices to bound the two expressions
\begin{align}
\label{eq:ikk_int1}
&\delta \int_{\mathbb{R}^{3N-3}} \lambda(x,y,\bold{\hat{x}})^{-4} f_{\infty}(x,\bold{\hat{x}}) f_{\infty}(y,\bold{\hat{x}}) \Phi(x,y,\bold{\hat{x}}) \,d\bold{\hat{x}},\\
\label{eq:ikk_int2}
&\int_{\mathbb{R}^{3N-3}} \partial_{x_j}^{\alpha+\beta} |x-x_j| |x-x_j| \psi(x,\bold{\hat{x}}) \psi(y,\bold{\hat{x}}) \Phi(x,y,\bold{\hat{x}}) \,d\bold{\hat{x}}.
\end{align}
The first is readily bounded as required using (\ref{eq:lam_bnd2}) of Lemma \ref{lem:lam_b2} with $b=4$.

It remains to bound (\ref{eq:ikk_int2}). We simplify the calculation by denoting $\sigma = \alpha + \beta$ and writing $\sigma = \sigma_1 + \dots + \sigma_5$ for some $|\sigma_s|=1$, $s=1, \dots, 5$. Define (in the same way as $\beta_{<i}$ and $\beta_{>i}$ above)
\begin{align*}
\sigma_{<i} =
\begin{cases}
0 &\text{ if } i=1\\
\sigma_1 &\text{ if } i=2\\
\sigma_1 + \dots + \sigma_{i-1} &\text{ if } 3 \le i \le 5,
\end{cases}
\qquad \sigma_{>i} =
\begin{cases}
0 &\text{ if } i=5\\
\sigma_5 &\text{ if } i=4\\
\sigma_{i+1} + \dots + \sigma_{5} &\text{ if } 1 \le i \le 3.
\end{cases}
\end{align*}
We now apply the same method used above, that is, we transfer successive first order derivatives via integration by parts. At each step we leave as a remainder the term where the derivative falls on $\psi(x,\bold{\hat{x}}) \psi(y,\bold{\hat{x}}) \Phi(x,y,\bold{\hat{x}})$.                                                                                                                                                                                                                      
Since $|\sigma|=5$ is odd, the result after this procedure has occured five times is that (\ref{eq:ikk_int2}) is precisely equal to minus the same integral plus remainder terms. This explains the $\frac{1}{2}$-factor in the following formula,
\begin{multline*}
\int_{\mathbb{R}^{3N-3}} \partial_{x_j}^{\sigma} |x-x_j| |x-x_j| \psi(x,\bold{\hat{x}}) \psi(y,\bold{\hat{x}}) \Phi(x,y,\bold{\hat{x}}) \,d\bold{\hat{x}} \\
= \frac{1}{2}\sum_{i=1}^{5} (-1)^i \int_{\mathbb{R}^{3N-3}} \partial_{x_j}^{\sigma_{>i}} |x-x_j| \partial_{x_j}^{\sigma_{<i}} |x-x_j| \partial_{x_j}^{\sigma_i}\big(\psi(x,\bold{\hat{x}}) \psi(y,\bold{\hat{x}}) \Phi(x,y,\bold{\hat{x}})\big) \,d\bold{\hat{x}}.
\end{multline*}
By (\ref{eq:modx_lam}), each of these integrals can be bounded by the right-hand side of (\ref{eq:itkk}) for a new constant $C'$. This completes the proof in the case where $j \in P^c \cap S^c$.

Finally, we must bound (\ref{eq:ijk}) for when $j=k$ but where $j \in P^*$ or $j \in S^*$. We assume that $j \in P^*$, the case of $j \in S^*$ is similar. Hence we need only consider $|\alpha|=1$. To bound the integral, we first apply integration by parts to obtain
\begin{align*}
I_{j,j} &= -\int_{\mathbb{R}^{3N-3}} |x-x_j|\, \partial_{x_j}^{\beta+\alpha} |y-x_j|\, \psi(x,\bold{\hat{x}}) \psi(y,\bold{\hat{x}})  \Phi(x,y,\bold{\hat{x}}) \,d\bold{\hat{x}}
\\ 
&\qquad-\int_{\mathbb{R}^{3N-3}} |x-x_j|\, \partial_{x_j}^{\beta} |y-x_j|\, \partial_{x_j}^{\alpha}\big(\psi(x,\bold{\hat{x}}) \psi(y,\bold{\hat{x}})  \Phi(x,y,\bold{\hat{x}})\big) \,d\bold{\hat{x}}.
\end{align*}
By Lemma \ref{particle_ineqs} we have $|x-x_j| < \delta/2$ when $\Phi(x,y,\bold{\hat{x}}) \ne 0$. Along with (\ref{eq:modx_lam}) and (\ref{eq:lam_bnd}) we then get
\begin{align*}
|I_{j,j}| &\le C\delta \int_{\mathbb{R}^{3N-3}} \lambda(x,y,\bold{\hat{x}})^{-4} f_{\infty}(x,\bold{\hat{x}}) f_{\infty}(y,\bold{\hat{x}}) \Phi(x,y,\bold{\hat{x}}) \,d\bold{\hat{x}}\\
&\qquad+ C\int_{\mathbb{R}^{3N-3}} \lambda(x,y,\bold{\hat{x}})^{-2} f_{\infty}(x,\bold{\hat{x}}) f_{\infty}(y,\bold{\hat{x}}) \big(\Phi(x,y,\bold{\hat{x}}) + |\nabla\Phi(x,y,\bold{\hat{x}})|\big) \,d\bold{\hat{x}}
\end{align*}
for some $C$. The two terms are just (\ref{eq:ikk_int1}) and the right-hand side of (\ref{eq:itkk}) respectively, and hence can be suitably bounded. This completes all required cases.

\label{lem:ff_holder}
Let $|\alpha| = 4$, $j \in P^c$ and $k \in S^c$. Then the integrals

\begin{align}
\label{eq:ff_holder1}
\int_{\mathbb{R}^{3N-3}} \partial_{x_j}^{\alpha}|x-x_j| \psi(x,\bold{\hat{x}})  e^{F(y,\bold{\hat{x}})} \overline{\nabla_y \phi(y,\bold{\hat{x}})}\Phi(x,y,\bold{\hat{x}}) \,d\bold{\hat{x}},
\end{align}
\begin{align}
\label{eq:ff_holder2}
\int_{\mathbb{R}^{3N-3}} e^{F(x,\bold{\hat{x}})} \nabla_x \phi(x,\bold{\hat{x}}) \partial_{x_k}^{\alpha}|y-x_k| \overline{\psi(y,\bold{\hat{x}})} \Phi(x,y,\bold{\hat{x}}) \,d\bold{\hat{x}}
\end{align}
can be bounded as in (\ref{eq:ab3}).

We prove the bound for (\ref{eq:ff_holder1}), the case of (\ref{eq:ff_holder2}) is similar. We use the cutoff function $\xi \in C^{\infty}_c(\mathbb{R})$, introduced in (\ref{eq:chi_def}), to define
\begin{align*}
\chi_1(z) := \xi(8|z|), \qquad \chi_2(z) := 1- \chi_1(z)
\end{align*}
$z \in \mathbb{R}^3$. Then $\chi_1(z) \ne 0$ implies $|z| < 1/4$ and $\chi_2(z) \ne 0$ implies $|z| > 1/8$.

We write the integral (\ref{eq:ff_holder1}) as
\begin{align}
\label{eq:ff_split2}
&\int_{\mathbb{R}^{3N-3}} \big(\chi_1(x-x_j) + \chi_2(x-x_j)\big) \partial_{x_k}^{\alpha}|x-x_j| \psi(x,\bold{\hat{x}}) e^{F(y,\bold{\hat{x}})} \overline{\partial_y^m \phi(y,\bold{\hat{x}})} \Phi(x,y,\bold{\hat{x}}) \,d\bold{\hat{x}}.
\end{align}

Expanding this and using, for example, the comment before Lemma \ref{dcutoff_factors}, the integral involving $\chi_2$ can be bounded in absolute value by some constant multiplying
\begin{align*}
\int_{\mathbb{R}^{3N-6}} \int_{\{x_j : |x-x_j|>1/8\}} |x-x_j|^{-3} |\psi(x,\bold{\hat{x}}) e^{F(y,\bold{\hat{x}})} \nabla \phi(y,\bold{\hat{x}})| \Phi(x,y,\bold{\hat{x}}) \,dx_j d\bold{\hat{x}}_{1,j}.
\end{align*}
We then use (\ref{eq:phi_er}), (\ref{eq:phi_psi}) and that $F$ is uniformly bounded on $\mathbb{R}^{3N}$ to bound this integral by some constant multiplying (\ref{eq:ff_int}) of Proposition \ref{prop:ff} with, say, $R=1/2$.

We now consider the $\chi_1$ term of (\ref{eq:ff_split2}). Firstly, we recall the notation introduced in (\ref{eq:bx1})-(\ref{eq:bx4}), namely we can write
\begin{equation*}
(y,x,\bold{\hat{x}}_{1,j}) = (y,x_2, \dots, x_{j-1}, x, x_{j+1}, \dots, x_N).
\end{equation*}
Take any $\theta \in (0,1)$. We know that $\phi \in C^{1,\theta}(\mathbb{R}^{3N})$. In particular, using (\ref{eq:phi_er}) and (\ref{eq:phi_psi}) there exists a constant $C$ such that when $|x-x_j| < 1/4$,
\begin{gather}
\label{eq:phi_linf}
|\partial_y^m \phi(y,x,\bold{\hat{x}}_{1,j})| \le \left\lVert\nabla \phi\right\rVert_{L^{\infty}(B((y,\bold{\hat{x}}), 1/4))} \le Cf_{\infty}(y,\bold{\hat{x}}),\\
\label{eq:dphi_holder}
\big|\partial_y^m \phi(y,\bold{\hat{x}}) - \partial_y^m \phi(y,x,\bold{\hat{x}}_{1,j}) \big| \le |x-x_j|^{\theta}[\nabla\phi]_{\theta, B((y,\bold{\hat{x}}), 1/4)} \le C|x-x_j|^{\theta}f_{\infty}(y,\bold{\hat{x}}).
\end{gather}
The constant $C$ depends on $\theta$ but is independent of $x,y$ and $\bold{\hat{x}}$.

We now write the $\chi_1$ term in (\ref{eq:ff_split2}) as the sum of the following two integrals,
\begin{gather}
\label{eq:ff_split2a}
\int_{ \mathbb R^{3N-3}} \chi_1(x-x_j) \partial_{x_j}^{\alpha}|x-x_j| \psi(x,\bold{\hat{x}}) e^{F(y,\bold{\hat{x}})} \overline{\partial_y^m \phi(y,x,\bold{\hat{x}}_{1,j})} \Phi(x,y,\bold{\hat{x}}) \, d\bold{\hat{x}},\\

\nonumber
\int_{ \mathbb R^{3N-3}} \chi_1(x-x_j) \partial_{x_j}^{\alpha}|x-x_j| \psi(x,\bold{\hat{x}}) e^{F(y,\bold{\hat{x}})} \overline{\big(\partial_y^m \phi(y,\bold{\hat{x}}) - \partial_y^m \phi(y,x,\bold{\hat{x}}_{1,j}) \big)} \Phi(x,y,\bold{\hat{x}}) \, d\bold{\hat{x}}.
\end{gather}

The second integral can be bounded by some constant multiplying
\begin{align*}
\int_{ \mathbb R^{3N-3}} \lambda(x,y,\bold{\hat{x}})^{-3+\theta} f_{\infty}(x,\bold{\hat{x}}) f_{\infty}(y,\bold{\hat{x}}) \Phi(x,y,\bold{\hat{x}}) \, d\bold{\hat{x}}
\end{align*}
using (\ref{eq:dphi_holder}) and that $F$ is uniformly bounded. Lemma \ref{lem:lam_b2} can then be used to obtain the required bound.

It suffices to bound (\ref{eq:ff_split2a}). Integration by parts in the variable $x_j$ is used in (\ref{eq:ff_split2a}) to remove a single derivative from $\partial_{x_j}^{\alpha}|x-x_j|$.                                                                                                                                           
Take any $l \le \alpha$ with $|l|=1$. Integral (\ref{eq:ff_split2a}) can therefore be rewritten as
\begin{multline*}
\int_{ \mathbb R^{3N-3}} \partial^{l} \chi_1(x-x_j)\, \partial_{x_j}^{\alpha-l}|x-x_j| \, \psi(x,\bold{\hat{x}})\, e^{F(y,\bold{\hat{x}})}\, \overline{\partial_y^m \phi(y,x,\bold{\hat{x}}_{1,j})} \,\Phi(x,y,\bold{\hat{x}}) \,d\bold{\hat{x}}\\
-\int_{ \mathbb R^{3N-3}} \chi_1(x-x_j)\, \partial_{x_j}^{\alpha-l}|x-x_j| \,\overline{\partial_y^m \phi(y,x,\bold{\hat{x}}_{1,j})}\, \partial_{x_j}^{l} \big(e^{F(y,\bold{\hat{x}})} \psi(x,\bold{\hat{x}}) \Phi(x,y,\bold{\hat{x}}) \big) \,d\bold{\hat{x}}.
\end{multline*}

We can use (\ref{eq:modx_lam}), (\ref{eq:phi_linf}) and the fact that both $F$ and $\nabla F$ are uniformly bounded, to bound this in absolute value by some constant multiplying
\begin{align*}
\int_{\mathbb{R}^{3N-3}} \lambda(x,y,\bold{\hat{x}})^{-2} f_{\infty}(x,\bold{\hat{x}}) f_{\infty}(y,\bold{\hat{x}}) \big(\Phi(x,y,\bold{\hat{x}})+|\nabla \Phi(x,y,\bold{\hat{x}})|\big) \,d\bold{\hat{x}}.
\end{align*}
The relevant bound then follows by Lemma \ref{lem:lam_b2} and Corollary \ref{cor:lam_b}.

\label{thm:fs}
For all $0<r<R$ we have a constant $C$, depending on $r$ and $R$, such that
\begin{equation}
\left\lVert\phi'\right\rVert_{W^{2,\infty}(B(\bold{x}, r))} \le C\left\lVert\phi'\right\rVert_{L^{\infty}(B(\bold{x}, R))}
\end{equation}
for all $\bold{x} \in \mathbb{R}^{3N}$. The constant does not depend on $\mathbf x$.

\label{lem:ddg}
$G, \nabla G \in L^{\infty}(\mathbb{R}^{3N})$. Also, for all $j,k = 1, \dots N$ and $r,s \in \{1,2,3\}$ there exists some $C$ such that
\begin{align*}
|\partial^{e_r}_{x_j} \partial^{e_s}_{x_k} G(\mathbf x)| \le 
\begin{cases}
C\big(1 - \log\big(\min\{1,\, |x_j|^2+|x_k|^2\}\big)\big) &\text{ if } j \ne k \text{ and } r=s\\
C &\text{ otherwise}.
\end{cases}
\end{align*}

\label{cor:d2phi}
For all $0<r<R<1$ there exists $C$, depending on $r$ and $R$, such that for any non-empty cluster $P$ and any $\eta \in \mathbb{N}_0^3$ with $|\eta|=1$,
\begin{align*}
\left\lVertD_P^{\eta} \nabla \phi\right\rVert_{L^{\infty}(B(\bold{x}, r \nu_P(\bold{x})))} \le C(1-\log\nu_P(\mathbf x)) \left\lVert\phi\right\rVert_{L^{\infty}(B(\bold{x}, R))}
\end{align*}
for all $\bold{x}$ with $\nu_P(\mathbf x) > 0$.

By the definition of cluster derivatives, (\ref{eq:cd}), it follows from Lemma \ref{lem:ddg} that there is some $C$ such that
\begin{align}
\label{eq:ddg}
|D_P^{\eta}\nabla G(\mathbf x)| \le C(1 - \log(\nu_P(\mathbf x)))

\end{align}
for all $\mathbf x$ with $\nu_P(\mathbf x) > 0$.

By (\ref{lam_lip}), we get that $(1-r)\nu_P(\bold{x}) \le \nu_P(\bold{y})$ for all $\bold{y} \in B(\bold{x}, r\nu_P(\bold{x}))$. Therefore, for $C$ as in (\ref{eq:ddg}), we have for all $\bold{x}$ with $\nu_P(\mathbf x)>0$,
\begin{align}
\label{eq:ddg2}
\left\lVertD_P^{\eta} \nabla G\right\rVert_{L^{\infty}(B(\bold{x}, r\nu_P(\bold{x})))} &\le C(1 - \log(1-r) - \log(\nu_P(\mathbf x)))\\
&\le C'(1 - \log(\nu_P(\mathbf x)))
\end{align}
for some $C'$ depending on $r$.


We recall from the definition, (\ref{phi_def}), that $\phi = e^{-F}\psi$. Therefore $\phi = e^G\phi'$. Then, we have $\nabla \phi = e^G \phi' \nabla G + e^G \nabla \phi'$. And therefore the following formula holds,
\begin{align*}
D_P^{\eta} \nabla \phi = \big(D_P^{\eta} \nabla G + D_P^{\eta} G\, \nabla G\big)e^G\phi' + e^G D_P^{\eta} \phi'\, \nabla G +  e^G D_P^{\eta}G\, \nabla \phi' +  e^G D_P^{\eta}\nabla \phi'.
\end{align*}
Taking the norm and using that $G,\nabla G \in L^{\infty}$ by Lemma \ref{lem:ddg} we can then obtain $C$ such that
\begin{align}
\label{eq:ddphi_b1}
\left\lVertD_P^{\eta} \nabla \phi\right\rVert_{L^{\infty}(B(\bold{x}, r\nu_P(\bold{x})))} &\le C(1-\log(\nu_P(\mathbf x))) \left\lVert\phi'\right\rVert_{W^{2,\infty}(B(\bold{x}, r\nu_P(\bold{x})))}.
\end{align}
Using that $\nu_P \le 1$, we then apply Theorem \ref{thm:fs} followed by a use of the equality $\phi = e^G\phi'$ to obtain the required result.
